"""Persistent wired transport; delivers verified PCM immediately to a callback.

This module does not load ASR/LLM/TTS or replace the accepted board player.
Closing the active socket cancels delivery; a future turn opens a fresh one.
"""
import http.client
import json
import select
import socket
import threading
import time

from common.asr_wire import context, encode_context
from common.voice_channel import CONTENT_TYPE, ChannelState, read_frame


class VoiceChannel:
    def __init__(self, host, port=8792, *, feedback=False,identity_query=False,visual_question=False):
        self.host, self.port = host, port
        self.feedback=bool(feedback)
        self.identity_query=bool(identity_query)
        self.visual_question=bool(visual_question)
        self.connection = None
        self.socket = None
        self.cancelled = threading.Event()
        self.inflight = threading.Lock()

    def cancel(self):
        self.cancelled.set()
        connected = self.socket
        if connected:
            try: connected.shutdown(socket.SHUT_RDWR)
            except OSError: pass

    def close(self):
        self.cancel()
        if self.connection: self.connection.close()
        self.connection = self.socket = None

    def exchange(self, meta, pcm, on_frame, *, is_current=lambda: True,enrollment_state=None,conversation=None,visual_entry=False,profile_token=None,wake_entry=False,speaker_visual=None,face_gallery=None):
        """Callback cost/backpressure counts toward the same total turn budget."""
        context(meta, pcm)
        if not self.inflight.acquire(blocking=False): raise RuntimeError('Channel already in use')
        self.cancelled.clear()
        deadline = time.monotonic() + meta['budget_ms']/1000
        timer = threading.Timer(meta['budget_ms']/1000, self.cancel)
        timer.daemon = True
        state = ChannelState(meta)
        try:
            if not is_current(): raise InterruptedError('Stale turn before sending')
            if self.connection is None:
                self.connection = http.client.HTTPConnection(self.host, self.port, timeout=meta['budget_ms']/1000)
            connected=self.connection.sock
            if connected is not None and select.select([connected],[],[],0)[0]:
                if not connected.recv(1,socket.MSG_PEEK):self.connection.close()
            if self.connection.sock is None:
                self.connection.connect()
            self.socket = self.connection.sock
            remaining=deadline-time.monotonic()
            if remaining<=0:raise TimeoutError('Channel connection budget expired')
            self.socket.settimeout(remaining)
            self.socket.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
            timer.interval=remaining
            timer.start()
            headers={'Content-Type':'application/octet-stream','X-Aura-Asr':encode_context(meta),
                     'X-Aura-Motion':'speech-v1'}
            if conversation is not None:
                from common.conversation_store import conversation_id
                headers['X-Aura-Conversation']='v1:'+conversation_id(conversation)
            if speaker_visual is not None:
                if conversation is None:raise ValueError('Speaker observations require a durable conversation')
                from common.speaker_visual import encode_visual_header
                headers['X-Aura-Speaker-Visual']=encode_visual_header(speaker_visual,meta)
            if face_gallery is not None:
                from common.face_binding_wire import encode_gallery_header
                headers['X-Aura-Face-Gallery']=encode_gallery_header(face_gallery,meta)
            if profile_token is not None:
                import re
                if conversation is None or enrollment_state is not None or not re.fullmatch('[0-9a-f]{64}',profile_token):
                    raise ValueError('Profile token requires a durable ordinary conversation')
                headers['X-Aura-Profile']='v1:'+profile_token
            if visual_entry and wake_entry:raise ValueError('Conflicting entry modes')
            entry_mode='wake-word-v1' if wake_entry else 'visual-speech-v1' if visual_entry else None
            if entry_mode:headers['X-Aura-Entry']=entry_mode
            if self.visual_question:headers['X-Aura-Visual']='frame-question-v1'
            if self.feedback:headers['X-Aura-Features']='thinking-feedback-v1'
            if enrollment_state is not None:
                headers['X-Aura-Identity']='enrollment-active-v1' if enrollment_state else 'enrollment-v1'
                if self.identity_query:headers['X-Aura-Identity-Query']='current-face-v1'
            self.connection.request('POST', '/v1/voice/channel', pcm, headers)
            response = self.connection.getresponse()
            if entry_mode and response.status==422:
                from common.handsfree_entry import EntryRejected
                raw=response.read(4097)
                if len(raw)<=4096 and json.loads(raw).get('code')=='entry_rejected':raise EntryRejected('No valid initial speech')
            if wake_entry and response.status==204:
                if response.getheader('X-Aura-Entry')!='wake-word-v1':
                    raise RuntimeError('Wake response lacks negotiation')
                response.read()
                if self.cancelled.is_set() or not is_current() or time.monotonic()>=deadline:
                    raise InterruptedError('Wake response expired')
                return {'wake_only':True}
            if response.status != 200 or response.getheader('Content-Type') != CONTENT_TYPE:
                raise RuntimeError('Voice channel HTTP ' + str(response.status))
            if self.visual_question and response.getheader('X-Aura-Visual')!='frame-question-v1':
                raise RuntimeError('Voice host does not support visual questions')
            if conversation is not None and response.getheader('X-Aura-Conversation')!='v1':
                raise RuntimeError('Voice host does not support durable conversations')
            if entry_mode and response.getheader('X-Aura-Entry')!=entry_mode:
                raise RuntimeError('Voice host does not support visual speech entry')
            if response.getheader('Transfer-Encoding') != 'chunked':
                raise ValueError('Voice channel is not streamed')
            while not state.ended:
                if self.cancelled.is_set() or not is_current():raise InterruptedError('Voice channel cancelled')
                header, payload = read_frame(response)
                if self.cancelled.is_set() or not is_current(): raise InterruptedError('Voice channel cancelled')
                if time.monotonic() >= deadline: raise TimeoutError('Voice channel expired')
                if 'binding_request' in header:
                    if header.get('kind')!='transcript' or 'identity_request' not in header:
                        raise ValueError('Binding metadata requires the original identity token')
                    from common.face_binding_wire import validate_binding_request
                    validate_binding_request(header['binding_request'],meta)
                state.accept(header, payload)
                if header['kind'] == 'error': raise RuntimeError(header['error'])
                on_frame(header, payload)
            if response.read(1): raise ValueError('Data after channel completion')
            if self.cancelled.is_set() or not is_current(): raise InterruptedError('Turn expired after reception')
            return {'sample_count': state.samples, 'pcm_sha256': state.digest.hexdigest(),
                    'reply_text': state.text, 'network_complete': True, 'playback_verified': False}
        except Exception:
            cancelled=self.cancelled.is_set() or not is_current()
            self.close()
            if cancelled:raise InterruptedError('Voice channel cancelled') from None
            raise
        finally:
            timer.cancel()
            self.inflight.release()

    def visual_frame(self,meta,token,*,is_current=lambda:True):
        import base64
        from board.runtime.visual_capture import current_frame
        if self.cancelled.is_set() or not is_current():raise InterruptedError('Visual capture cancelled')
        body={'context':meta,'token':token}
        try:
            frame,jpeg=current_frame(meta['board_boot_id'],is_current=lambda:not self.cancelled.is_set() and is_current())
            body.update(frame=frame,jpeg_base64=base64.b64encode(jpeg).decode())
        except (OSError,ValueError,KeyError,TypeError):body['unavailable']='fresh_frame_unavailable'
        if self.cancelled.is_set() or not is_current():raise InterruptedError('Visual upload cancelled')
        connection=http.client.HTTPConnection(self.host,self.port,timeout=3)
        try:
            connection.request('POST','/v1/voice/visual/frame',json.dumps(body).encode(),{'Content-Type':'application/json'})
            response=connection.getresponse();raw=response.read(4097)
            if response.status!=200 or len(raw)>4096 or not json.loads(raw).get('accepted'):raise RuntimeError('Visual frame rejected')
        finally:connection.close()

    def identity_result(self,meta,token,reply,*,sequence=None,final=True,binding_receipt=None):
        from common.voice_enrollment import render
        render(reply)
        connection=http.client.HTTPConnection(self.host,self.port,timeout=3)
        try:
            body={'context':meta,'token':token,'reply':reply}
            if binding_receipt is not None:
                if final is not True or reply['code'] not in ('registered','already_known'):
                    raise ValueError('Face receipt requires final original success result')
                from common.face_binding_wire import canonical
                if len(canonical(binding_receipt))<=4096:body['binding_receipt']=binding_receipt
            if sequence is not None:body.update(sequence=sequence,final=final)
            raw_body=json.dumps(body).encode()
            if len(raw_body)>4096 and 'binding_receipt' in body:
                # Retain the original result but provide no commit proof. The
                # host must keep unified binding incomplete, never truncate it.
                body.pop('binding_receipt');raw_body=json.dumps(body).encode()
            if len(raw_body)>4096:raise ValueError('Original identity result exceeds bound')
            connection.request('POST','/v1/voice/identity/result',raw_body,{'Content-Type':'application/json'})
            response=connection.getresponse();raw=response.read(4097)
            if response.status!=200 or len(raw)>4096 or not json.loads(raw).get('accepted'):
                raise RuntimeError('Identity voice result rejected')
        finally:connection.close()

    def submit_face_gallery(self,meta,packet,*,is_current=lambda:True):
        from common.face_binding_wire import canonical,validate_packet,packet_sha256
        packet=validate_packet(packet,meta);digest=packet_sha256(packet)
        if not is_current():raise InterruptedError('Stale face gallery metadata')
        connection=http.client.HTTPConnection(self.host,self.port,timeout=.4)
        try:
            body=canonical(dict(context=meta,packet=packet))
            if len(body)>24576:return False
            connection.request('POST','/v1/voice/identity/gallery',body,{'Content-Type':'application/json'})
            response=connection.getresponse();raw=response.read(4097)
            if (response.status!=200 or len(raw)>4096):return False
            result=json.loads(raw)
            if not is_current():raise InterruptedError('Expired face gallery metadata')
            return result=={'accepted':True,'packet_sha256':digest}
        finally:connection.close()

board/runtime/board_business.py.text:
"""Explicit assembly of board-owned dialogue, memory and local control.

Importing this module starts no device, network, model or task. The assembly is
an opt-in candidate: the Store's synthetic-data gate remains in force. Existing
GTK/recording/player owners are supplied, rather than copied or replaced here.
"""
from dataclasses import dataclass
from pathlib import Path
import copy
import json
import os
import re
import stat
import threading
import time
import uuid

from board.runtime.audio.board_dialogue_jobs import BoardDialogueJobs, BoardCapabilityNotReady
from board.runtime.board_dialogue import BoardDialogueController, BoardReply, StaleGeneration, DIALOGUE_ROUTE
from board.runtime.board_dialogue_client import InferenceHttpClient, ModelRequestError
from board.runtime.board_memory_policy import BoardContextBuilder, BoardMemoryCommands, BoardSummaryClient
from common.board_memory import BoardMemoryStore, BoardMemoryWorker, MemoryBusy
from common.board_memory_backoff import BoardMemoryBackoffWorker
from common.board_timeline_clock import StableTimelineClock, ClockUnavailable
from common.profile_access import ProfileAccess, identifier
from common.profile_selection import selection


@dataclass(frozen=True)
class BoardBusinessConfig:
    private_root: str
    utc_bounds: tuple
    model_host: str = '192.168.50.1'
    model_port: int = 8797
    timeout_ms: int = 120000
    timezone: str = 'America/Los_Angeles'
    entry_mode: str = 'voice_first'
    data_origin: str = 'synthetic'
    visual_device_id: object = None
    bootstrap_receipt: object = None
    bootstrap_receipt_sha256: object = None
    retention_enabled: bool = False

    def __post_init__(self):
        if type(self.retention_enabled) is not bool:
            raise ValueError('Retention requires an explicit configuration boolean')
        if self.data_origin == 'board' and (not isinstance(self.bootstrap_receipt, str)
                or not Path(self.bootstrap_receipt).is_absolute()
                or not isinstance(self.bootstrap_receipt_sha256, str)
                or re.fullmatch(r'[0-9a-f]{64}', self.bootstrap_receipt_sha256) is None):
            raise ValueError('Production requires its committed private migration receipt')
        if self.data_origin not in ('synthetic', 'board'):
            raise ValueError('Choose a distinct synthetic candidate or board-owned store')
        if not Path(self.private_root).is_absolute():
            raise ValueError('An absolute board-private candidate root is required')
        if self.model_host != '192.168.50.1' or type(self.model_port) is not int or not 1024 <= self.model_port <= 65535:
            raise ValueError('Use the pinned Ethernet model-only endpoint')
        if self.entry_mode not in ('voice_first', 'visual'):
            raise ValueError('Choose the explicit board entry policy')
        if type(self.timeout_ms) is not int or not 1000 <= self.timeout_ms <= 120000:
            raise ValueError('Invalid original turn deadline')
        if not isinstance(self.utc_bounds, (tuple, list)) or len(self.utc_bounds) != 2:
            raise ValueError('Explicit trusted UTC bounds are required')
        if self.visual_device_id is not None and (not isinstance(self.visual_device_id, str)
                or not re.fullmatch(r'[A-Za-z0-9_.:-]{1,160}', self.visual_device_id)):
            raise ValueError('Invalid explicit visual device scope')


class LocalProfileSelections:
    """Use the existing ProfileAccess on the board, with no Windows endpoint.

    Local operator control calls issue() after authentication. The existing GTK
    selection file may carry its returned token; loading the file never selects
    a profile. resolve() checks the live, same-process grant when the user clicks.
    A name, face match or speaker candidate is never accepted as a grant.
    """
    def __init__(self, access, boot_id, require_profile, *, wall_clock):
        if not isinstance(access, ProfileAccess) or not callable(require_profile):
            raise TypeError('Board ProfileAccess and local profile catalogue are required')
        self.access, self.boot_id, self.require_profile = access, boot_id, require_profile
        self.wall_clock = wall_clock
        self.lock = threading.RLock()
        self.issued = {}

    def issue(self, profile_id, operator_key, *, ttl=900, profile_name='个人档案'):
        self.access.authenticate(operator_key)
        identifier(profile_id)
        self.require_profile(profile_id)
        if not isinstance(profile_name, str) or not 1 <= len(profile_name) <= 40 or any(ord(c) < 32 for c in profile_name):
            raise ValueError('Invalid profile display name')
        now = self.wall_clock()  # Check clock before issuing a capability.
        meta = dict(board_boot_id=self.boot_id, session_id=uuid.uuid4().hex)
        token, grant = self.access.issue(profile_id, meta, ttl=ttl)
        with self.lock:
            active = tuple(self.access.grants.values())
            self.issued = {old: record for old, record in self.issued.items()
                           if any(value is record[0] for value in active)}
            self.issued[token] = (grant, meta)
        return dict(mode='profile', **meta, profile_id=profile_id, profile_name=profile_name,
                    conversation_id=uuid.uuid4().hex, access_token=token,
                    expires_in_seconds=ttl, expires_unix=now + ttl)

    def resolve(self, value, boot_id):
        if boot_id != self.boot_id:
            raise PermissionError('Profile request belongs to another board boot')
        value = selection(value, self.boot_id)
        self.require_profile(value['profile_id'])
        grant = self.access.resolve(value['access_token'], value)
        if grant.profile_id != value['profile_id']:
            raise PermissionError('Profile token belongs to another profile')
        return dict(scope=dict(kind='profile', id=grant.profile_id, grant=grant),
                    session_id=value['session_id'], conversation_id=value['conversation_id'])

    def release(self, selected):
        grant = selected.get('scope', {}).get('grant')
        if grant is None:
            raise PermissionError('No original board profile grant')
        if grant.actor != (self.boot_id, selected['session_id']):
            raise PermissionError('Profile release belongs to another board interaction')
        with self.access.lock:
            # Releasing an obsolete selection must not revoke another grant.
            if any(value is grant for value in self.access.grants.values()):
                self.access.revoke(dict(board_boot_id=self.boot_id, session_id=selected['session_id']))
        with self.lock:
            self.issued = {key: value for key, value in self.issued.items() if value[0] is not grant}

    def close(self):
        with self.lock:
            issued, self.issued = tuple(self.issued.values()), {}
        with self.access.lock:
            for grant, meta in issued:
                if any(value is grant for value in self.access.grants.values()):
                    self.access.revoke(meta)


class LocalIdentityReplies:
    """Existing board face FSM, with its original consent/target checks.

    Private snapshots and enrollment commands remain local. Each stage uses the
    same ongoing channel and player; success is rendered only after the original
    flow has verified its commit receipt. No second microphone/player is opened.
    """
    streaming_reply = True
    def __init__(self, boot_id, snapshot, command, *, clock=time.monotonic, now_ms=None,
                 enrollment_factory=None):
        from board.identity.voice_enrollment import VoiceEnrollment
        from board.interaction.ui_contract import millis
        self.snapshot, self.clock = snapshot, clock
        self.original_command = command
        self.business = self.bridge = None
        self.flow = (enrollment_factory or VoiceEnrollment)(boot_id, snapshot, command,
            simple=True, clock=clock, now_ms=now_ms or millis)

    def attach_speaker_business(self, business, readback=None):
        if self.flow.public()['active']:
            raise RuntimeError('Attach board speaker business before starting a face workflow')
        from board.runtime.audio.face_binding_bridge import FaceBindingBridge
        self.business = business
        self.bridge = FaceBindingBridge(self.snapshot, self.original_command, readback,
                                        clock=lambda: round(self.clock()*1000))
        self.flow.snapshot, self.flow.command = self.bridge.snapshot, self.bridge.command

    def reset(self):
        self.flow.reset()
        if self.business is not None:
            self.business.reset()

    def public(self):
        state = self.flow.public()
        if self.business is not None:
            state = dict(state, active=state['active'] or self.business.public()['active'],
                         speaker=self.business.public())
        return state

    def _visual(self, job):
        from common.speaker_visual import build_visual, unavailable
        try:
            return build_visual(job.capture_snapshot, self.snapshot(), job.meta, round(self.clock()*1000))
        except (OSError, ValueError, KeyError, TypeError):
            return unavailable(job.meta, 'VISUAL_PROVIDER_UNAVAILABLE')

    def _gallery(self, job):
        if self.bridge is None or self.bridge.readback is None:
            return None
        try:
            return self.bridge.readback.read(job.meta, self.snapshot())
        except (OSError, ValueError, KeyError, TypeError):
            return None

    def __call__(self, text, *, job, controller, is_current, cancel_event, reply_sink=None):
        from common.binding_intent import binding_intent, face_enrollment_text
        from common.voice_enrollment import render, result
        def current():
            if not is_current() or cancel_event.is_set() or self.clock() >= job.deadline:
                return False
            check = getattr(controller.store, 'check_turn_current', None)
            if check is not None:
                try:
                    check(job.meta['request_id'], generation=job.meta['generation'])
                except Exception:
                    return False
            return True
        def initial(interpreted=None):
            if not current():
                raise StaleGeneration('Identity turn is no longer current')
            intent = binding_intent(text)
            if intent['kind'] == 'invalid_name':
                value = result('bad_name')
            else:
                interpreted = interpreted or face_enrollment_text(text, active=self.flow.public()['active'])
                value = self.flow.handle(interpreted, copy.deepcopy(job.capture_snapshot),
                                         is_current=current)
                if value is None:
                    raise BoardCapabilityNotReady('identity_intent')
            return value
        budget = int((job.deadline - self.clock()) * 1000)
        if budget < 1:
            raise TimeoutError('Original capture deadline expired before local identity')
        kwargs = dict(scope=job.scope, session_id=job.meta['session_id'], generation=job.meta['generation'],
            budget_ms=budget, turn_id=job.meta['request_id'], cancel_event=cancel_event,
            metadata=dict(source_id=job.context_source_id, evidence='statement') if job.context_source_id else
                     dict(evidence='statement'))
        if reply_sink is None:
            raise BoardCapabilityNotReady('owned_identity_cue_stream')
        def produce(emit):
            from contextlib import nullcontext
            from common.binding_api import response as binding_response
            from common.voice_enrollment import enrollment_requested, identity_query_requested
            exchange = None
            board_text = None
            try:
                if self.business is not None:
                    options = dict(is_current=current, cancel_event=cancel_event, deadline=job.deadline)
                    from common.feature_intents import speaker_query_requested
                    if speaker_query_requested(text):
                        # Skip the unified enrollment router: a status question
                        # must not become one of its three captured samples.
                        spoken=self.business.turn(job.meta,text,job.pcm,**options)
                        if spoken is None:
                            raise BoardCapabilityNotReady('speaker_status_result')
                        emit(BoardReply(spoken,'friendly'),final_cue=True)
                        return
                    routed = (self.business.route(job.meta, text, job.pcm,
                                visual=self._visual(job), gallery_packet=self._gallery(job), **options)
                              if self.business.config['enabled'] else None)
                    decision = binding_response(routed, job.meta)['decision'] if routed is not None else None
                    route = decision['route'] if decision is not None else 'ordinary'
                    if route == 'device_reply':
                        emit(BoardReply(decision['reply'], 'friendly'), final_cue=True)
                        return
                    if route == 'ordinary_skip_speaker':
                        return DIALOGUE_ROUTE
                    if route == 'face_exchange':
                        exchange = self.business.begin_face_exchange(job.meta, job.pcm, routed, self.bridge,
                                    job.capture_snapshot, text, **options)
                        board_text = routed['binding_request']['board_text']
                    else:
                        spoken = self.business.turn(job.meta, text, job.pcm, **options)
                        if spoken is not None:
                            emit(BoardReply(spoken, 'friendly'), final_cue=True)
                            return
                        if (not self.flow.public()['active'] and not enrollment_requested(text)
                                and not identity_query_requested(text)):
                            # A bare self-name statement is ordinary dialogue,
                            # not consent to start an identity enrollment.
                            return DIALOGUE_ROUTE
                with exchange.scope() if exchange is not None else nullcontext():
                    value = initial(board_text)
                    guiding = value['code'] in ('sample_front', 'sample_auto')
                    def deliver(value, final):
                        if not current():
                            raise StaleGeneration('Sampling guide no longer owns this turn')
                        spoken = exchange.transform(value, final=final) if exchange is not None else render(value)
                        emit(BoardReply(spoken, 'friendly'), final_cue=final)
                    deliver(value, not guiding)
                    if guiding:
                        self.flow.guide(deliver, is_current=current)
            finally:
                if exchange is not None:
                    exchange.cancel()
        return controller.prepare_local_sequence(text, produce, reply_sink, **kwargs)


def board_entry_policy(mode, boot_id, snapshot, *, now_ms):
    """The historical 'visual' flag is also used by voice-first barge capture."""
    if mode == 'voice_first':
        # BoardDialogueJobs already validated current audio owner, PCM and ASR.
        # This path must not start requiring a face after wake-word acceptance.
        return lambda meta, captured, text, *, is_current: (
            meta.get('board_boot_id') == boot_id and is_current())
    if mode != 'visual' or not callable(snapshot):
        raise ValueError('A local visual provider is required for visual entry')
    def admit(meta, captured, text, *, is_current):
        from board.runtime.audio.attention_gate import read_attention
        if not is_current() or not isinstance(captured, dict):
            return False
        now = now_ms()
        stamp = captured.get('observed_mono_ms')
        if type(stamp) is not int or not 0 <= now - stamp <= 120000:
            return False
        before, _ = read_attention(captured, boot_id, stamp)
        current, _ = read_attention(snapshot(), boot_id, now)
        return bool(before and current and before['key'] == current['key'] and is_current())
    return admit


class _BoardWriterLock:
    """Kernel-held POSIX lifetime lock in the actual board-private directory."""
    def __init__(self, root, boot_id):
        if os.name != 'posix':
            raise RuntimeError('Real board storage requires the POSIX board runtime')
        import fcntl
        self.fd = None
        root = Path(root).absolute()
        if root.resolve() != root or any(part.casefold() == 'win共享文件' for part in root.parts):
            raise ValueError('Board memory cannot be stored through a shared/symlink directory')
        if not root.is_dir():
            raise ValueError('Migrate the private production directory before opening its writer')
        info = root.stat()
        if info.st_uid != os.getuid() or info.st_mode & 0o077 or not stat.S_ISDIR(info.st_mode):
            raise PermissionError('Board memory directory must be owned by this user and private')
        path = root/'writer.lock'
        fd = os.open(str(path), os.O_RDWR | os.O_CREAT | getattr(os, 'O_NOFOLLOW', 0), 0o600)
        try:
            info = os.fstat(fd)
            if info.st_uid != os.getuid() or info.st_mode & 0o077 or not stat.S_ISREG(info.st_mode):
                raise PermissionError('Invalid board writer lock')
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
            os.ftruncate(fd, 0)
            os.write(fd, json.dumps(dict(pid=os.getpid(), boot_id=boot_id)).encode())
            os.fsync(fd)
            self.fd = fd
            self.root = root
        except BaseException:
            os.close(fd)
            raise

    def close(self):
        if self.fd is not None:
            import fcntl
            fd, self.fd = self.fd, None
            try:
                fcntl.flock(fd, fcntl.LOCK_UN)
            finally:
                os.close(fd)


def create_board_business_runtime(config, boot_id, **kwargs):
    """Acquire the production single writer before constructing/opening Store."""
    proof = None
    if config.data_origin == 'board':
        from common.board_production_bootstrap import (
            verify_production_bootstrap, verify_production_bootstrap_receipt)
        verify_production_bootstrap_receipt(config.private_root, config.bootstrap_receipt, config.bootstrap_receipt_sha256)
    lease = _BoardWriterLock(config.private_root, boot_id) if config.data_origin == 'board' else None
    try:
        if config.data_origin == 'board':
            from board.runtime.board_speaker_business import _WriterLease
            speaker_lease = _WriterLease(Path(config.private_root)/'speaker', data_origin='board')
            try:
                proof = verify_production_bootstrap(config.private_root, config.bootstrap_receipt,
                    config.bootstrap_receipt_sha256, recovery_leases=(lease, speaker_lease))
            finally:
                speaker_lease.close()
        return BoardBusinessRuntime(config, boot_id, writer_lock=lease, bootstrap_proof=proof, **kwargs)
    except BaseException:
        if lease is not None:
            lease.close()
        raise


class BoardBusinessRuntime:
    def __init__(self, config, boot_id, *, asr, system_prompt, conversation_selection,
                 identity_snapshot=None, identity_command=None, profile_access=None,
                 require_profile=None, feedback_provider=None, playback_invalidator=None,
                 capture_idle=None, extra_handlers=None, clock=time.monotonic,
                 client=None, timeline=None, store=None, worker_factory=BoardMemoryBackoffWorker, writer_lock=None, bootstrap_proof=None):
        self.config, self.boot_id, self.clock = config, boot_id, clock
        if config.data_origin == 'board' and (not isinstance(writer_lock, _BoardWriterLock)
                or writer_lock.fd is None or writer_lock.root != Path(config.private_root).absolute()):
            raise RuntimeError('Use create_board_business_runtime for the exclusive board writer')
        if config.data_origin == 'board' and (not isinstance(bootstrap_proof, dict)
                or bootstrap_proof.get('receipt_verified') is not True
                or bootstrap_proof.get('data_origin') != 'board'
                or bootstrap_proof.get('profiles_migration_verified') is not True):
            raise RuntimeError('The production factory requires verified committed migration provenance')
        self.bootstrap_proof = dict(bootstrap_proof or {})
        self.initial_selection = dict(mode='explicit_selection_required', session_is_fresh=True)
        self.writer_lock = writer_lock
        if not re.fullmatch(r'[A-Za-z0-9_-]{1,96}', boot_id):
            raise ValueError('Invalid fresh board boot ID')
        self.client = client or InferenceHttpClient(config.model_host, config.model_port, clock=clock)
        if (self.client.host, self.client.port) != (config.model_host, config.model_port):
            raise ValueError('Model transport differs from configured pinned endpoint')
        root = Path(config.private_root)
        # One path per boot. A board restart cannot reload a former boot anchor.
        self.timeline = timeline or StableTimelineClock(boot_id, self.client.health_date_source_id(),
            self.client.validate_sample, utc_bounds=config.utc_bounds,
            anchor_path=root/'timeline'/('anchor-' + boot_id + '.json'), monotonic=clock)
        if self.timeline.boot_id != boot_id:
            raise ValueError('Timeline belongs to another board boot')
        self.access = profile_access or ProfileAccess(clock=clock)
        self.store = store or BoardMemoryStore(root/'timeline.sqlite3', clock=self.timeline.event_time,
                    profile_access=self.access, data_origin=config.data_origin)
        if self.store.clock != self.timeline.event_time or self.store.profile_access is not self.access:
            raise ValueError('Store must share the exact board clock and ProfileAccess')
        require_profile = require_profile or getattr(self.store, 'require_profile', None)
        self.profiles = (LocalProfileSelections(self.access, boot_id, require_profile,
                        wall_clock=self.timeline.event_time) if require_profile is not None else None)
        builder = BoardContextBuilder(system_prompt)
        capacity = min(768, builder.continuity_capacity())
        if capacity < 64:
            raise ValueError('The current persona leaves no stable continuity-summary capacity')
        self.controller = BoardDialogueController(self.store, self.client, board_boot_id=boot_id,
            system_prompt=system_prompt, asr=asr, clock=clock,
            context_builder=builder, command_handler=BoardMemoryCommands(self.store))
        handlers = dict(extra_handlers or {})
        from board.runtime.history_delete import LocalHistoryDelete
        handlers.setdefault('history_delete_preview', LocalHistoryDelete(self.store, self.timeline, clock=clock, zone=config.timezone))
        self.identity_handler = None
        if identity_snapshot is not None and identity_command is not None:
            identity = LocalIdentityReplies(boot_id, identity_snapshot, identity_command, clock=clock,
                                            now_ms=lambda: round(clock()*1000))
            self.identity_handler = identity
            if {'identity_enrollment', 'identity_query'} & set(handlers):
                raise ValueError('One board identity handler owns the original face FSM')
            handlers.update(identity_enrollment=identity, identity_query=identity)
        self.jobs = BoardDialogueJobs(self.controller,
            dict(enabled=True, host=config.model_host, port=config.model_port, timeout_ms=config.timeout_ms),
            boot_id, asr=asr, conversation_selection=conversation_selection,
            profile_resolver=self.profiles.resolve if self.profiles else None,
            profile_release=self.profiles.release if self.profiles else None,
            visual_entry_handler=board_entry_policy(config.entry_mode, boot_id, identity_snapshot,
                                                    now_ms=lambda: round(clock()*1000)),
            special_handlers=handlers, feedback_provider=feedback_provider,
            playback_invalidator=playback_invalidator, clock=clock,
            wall_clock=self.timeline.event_time, timezone=config.timezone, start_worker=False)
        self.jobs.identity_snapshot = identity_snapshot
        self.capture_idle = capture_idle
        self.speaker_business = None
        self.speaker_analysis_error = ''
        self._clock_refresh_lock = threading.Lock()
        self._clock_refresh_next = clock() + 600.
        self._clock_refresh_failures = 0
        self.clock_refresh_error = ''
        self.summary = BoardSummaryClient(self.client, board_boot_id=boot_id, clock=clock,
                                         final_summary_max_utf8_bytes=capacity)
        self.memory_worker = worker_factory(self.store, self.summary, idle=self.idle,
            compaction_guard_factory=self.timeline.compaction_guard, before_step=self._memory_before_step)
        self.visual_memory = None
        self.visual_policy = None
        if config.visual_device_id is not None:
            from board.runtime.visual_memory import VisualTimelineWorker
            self.visual_memory = VisualTimelineWorker(boot_id, self.store, self.timeline,
                                device_id=config.visual_device_id, monotonic=clock)
            from board.runtime.visual_policy import LocalVisualQueries
            visual_policy = LocalVisualQueries(self.store, self.visual_memory, self.timeline, zone=config.timezone)
            self.visual_policy = visual_policy
            self.jobs.special_handlers['structured_visual_query'] = visual_policy
            self.jobs.visual_intent_matcher = visual_policy.requested
        self.started = False
        self.closed = False
        self.close_complete = False

    def attach_speaker_business(self, business, *, face_readback=None):
        """Attach the one board CPU/three-store owner before starting UI jobs."""
        if self.started or self.closed or self.speaker_business is not None:
            raise RuntimeError('Attach speaker business once before startup')
        if (business.boot != self.boot_id or business.clock is not self.clock
                or business.wall_clock != self.timeline.event_time or business.data_origin != self.config.data_origin):
            raise ValueError('Speaker business must share the exact board boot, clock and data origin')
        if self.identity_handler is None:
            raise BoardCapabilityNotReady('board_identity_provider')
        self.identity_handler.attach_speaker_business(business, face_readback)
        self.speaker_business = business
        self.jobs.special_handlers['speaker_identity'] = self.identity_handler
        self.jobs.analysis_provider = self._submit_speaker_analysis

    def _submit_speaker_analysis(self, text, *, job, is_current, cancel_event):
        source = job.context_source_id
        if self.speaker_business is None or not isinstance(source, str) or not source.startswith('conversation:'):
            return None
        cid = source[len('conversation:'):]
        if not re.fullmatch(r'[0-9a-f]{32}', cid):
            return None
        def evidence(value):
            if (not is_current() or cancel_event.is_set() or self.clock() >= job.deadline
                    or value.get('status') != 'COMPLETE'):
                return
            # Keep the event identity, occurrence time and payload across retries.
            event_id = 'speaker:' + job.meta['request_id']
            metadata = dict(source_id=source, evidence='device_confirmed', speaker_known=False,
                occurred_utc=self.timeline.event_time(),
                claims=[dict(field='attribution', value='unconfirmed')])
            def check_current():
                if not is_current() or cancel_event.is_set() or self.clock() >= job.deadline:
                    raise StaleGeneration('Speaker evidence no longer owns its capture')
            # The existing speaker worker owns this bounded, cancellable retry.
            # Candidate IDs/vectors remain outside the shared timeline.
            for attempt in range(3):
                try:
                    check_current()
                    self.store.append_event(job.scope, event_id, 'device_event',
                        '本轮语音已形成归属线索，说话者身份仍未确认。', topic='语音归属',
                        metadata=metadata, guard=check_current)
                    return
                except StaleGeneration:
                    return
                except MemoryBusy:
                    if attempt == 2:
                        raise
                    delay = .025 * (attempt + 1)
                    if (not is_current() or cancel_event.is_set()
                            or self.clock() + delay >= job.deadline or cancel_event.wait(delay)):
                        return
        try:
            result = self.speaker_business.submit_analysis(job.meta, job.pcm, cid,
                visual=self.identity_handler._visual(job), is_current=is_current,
                gallery_provider=lambda: self.identity_handler._gallery(job),
                cancel_event=cancel_event, deadline=job.deadline, on_evidence=evidence)
            self.speaker_analysis_error = ''
            return result
        except (OSError, ValueError, RuntimeError) as exc:
            self.speaker_analysis_error = type(exc).__name__
            return None

    def initialize_clock(self, *, timeout=3., cancelled=lambda: False):
        if type(timeout) not in (int, float) or not 0 < timeout <= 10:
            raise ValueError('Use a bounded explicit Date sample')
        result = self.client.sample_health_date(self.timeline, deadline=self.clock() + timeout, cancelled=cancelled)
        self._clock_refresh_next = self.clock() + 600.
        self._clock_refresh_failures = 0
        self.clock_refresh_error = ''
        return result

    def _foreground_idle(self):
        return bool(not self.closed and callable(self.capture_idle) and self.capture_idle()
                    and self.jobs.idle and self.controller.idle
                    and (self.speaker_business is None or not self.speaker_business.health()['queued_or_active']))

    def _memory_before_step(self, cancelled):
        """Use the existing idle worker, outside every SQL/clock quality lease."""
        if cancelled() or not self._foreground_idle():
            return False
        if self.clock() < self._clock_refresh_next:
            return None
        if not self._clock_refresh_lock.acquire(blocking=False):
            return False
        try:
            self.client.sample_health_date(self.timeline, deadline=self.clock() + 1.,
                cancelled=lambda: cancelled() or not self._foreground_idle())
            self._clock_refresh_next = self.clock() + 600.
            self._clock_refresh_failures = 0
            self.clock_refresh_error = ''
            return True
        except (ModelRequestError, ClockUnavailable, OSError, ValueError) as exc:
            self._clock_refresh_failures += 1
            self._clock_refresh_next = self.clock() + min(60., 3.*2**min(self._clock_refresh_failures-1, 5))
            self.clock_refresh_error = type(exc).__name__
            return False
        finally:
            self._clock_refresh_lock.release()

    def idle(self):
        # Missing capture ownership must never permit destructive compaction.
        return self._foreground_idle() and self.timeline.safe_for_compaction()

    def start(self):
        if self.closed:
            raise RuntimeError('Board runtime is closed')
        self.timeline.event_time()  # No wall-clock fallback on first startup.
        if self.config.data_origin == 'board' and self.speaker_business is None:
            raise BoardCapabilityNotReady('board_speaker_business')
        if not self.started:
            self.jobs.start()
            if self.config.retention_enabled:
                self.memory_worker.start()
            if self.visual_memory is not None:
                self.visual_memory.start()
            self.started = True

    def make_barge_capture_factory(self, output, spoken_text, frontend_factory, *, capture_type=None,
                                  verifier_type=None):
        """Inject the existing echo/reference capture, using board ASR only."""
        def create():
            from board.runtime.audio.barge_verify import InterruptionVerifier
            from board.runtime.audio.board_capture import BoardBargeCapture
            verifier = (verifier_type or InterruptionVerifier)(lambda: dict(self.jobs.config), self.boot_id,
                transport=self.jobs.interruption_transport, clock=self.clock)
            try:
                return (capture_type or BoardBargeCapture)(output, frontend_factory=frontend_factory,
                                verifier=verifier, spoken_text=spoken_text)
            except Exception:
                verifier.close()
                raise
        return create

    def close(self):
        if self.close_complete:
            return
        self.closed = True
        visual_stopped = self.visual_memory.close() if self.visual_memory is not None else True
        self.jobs.close()
        self.memory_worker.close()
        speaker_stopped = self.speaker_business.close() if self.speaker_business is not None else True
        if self.profiles is not None:
            self.profiles.close()
        if self.writer_lock is not None:
            threads = (self.memory_worker.thread, self.jobs.thread, self.jobs.action_thread)
            if not visual_stopped or not speaker_stopped or any(thread is not None and thread.is_alive() for thread in threads):
                # Keep the kernel lock while an old worker could still touch
                # SQLite. The process exiting releases it automatically.
                raise RuntimeError('Board workers are still finishing; writer lock retained')
            self.writer_lock.close()
        if not visual_stopped:
            raise RuntimeError('Board visual worker is still finishing')
        if not speaker_stopped:
            raise RuntimeError('Board speaker worker is still finishing')
        self.close_complete = True

    def public(self):
        production = self.config.data_origin == 'board'
        held = self.writer_lock is not None and self.writer_lock.fd is not None
        proof = self.bootstrap_proof
        memory_thread = getattr(self.memory_worker, 'thread', None)
        return dict(mode='board-business-' + self.config.data_origin, data_origin=self.config.data_origin,
                    production_cutover=bool(production and self.started and held),
                    writer=dict(kind='board-local-single-writer', held=held, boot_id=self.boot_id),
                    receipt=dict(verified=bool(production and proof.get('receipt_verified') is True), data_origin=proof.get('data_origin'),
                        bundle_id=proof.get('bundle_id'), profiles_migration_verified=proof.get('profiles_migration_verified',False),
                        profiles_imported=proof.get('profiles_imported',0)),
                    retention=dict(enabled=self.config.retention_enabled,
                        running=bool(memory_thread and memory_thread.is_alive()),
                        initial_retention_enabled=proof.get('initial_retention_enabled',False)),
                    conversation_selection=dict(self.initial_selection),
                    started=self.started, closed=self.closed, clock=self.timeline.quality_snapshot(),
                    dialogue=self.jobs.public(), memory=self.memory_worker.health(),
                    close_complete=self.close_complete,
                    visual_timeline=self.visual_memory.public() if self.visual_memory is not None else dict(enabled=False),
                    visual_queries=self.visual_policy.public() if self.visual_policy is not None else dict(enabled=False),
                    speaker=self.speaker_business.health() if self.speaker_business is not None else dict(ready=False),
                    speaker_analysis_error=self.speaker_analysis_error,
                    clock_refresh=dict(error=self.clock_refresh_error,
                                       retry_in_seconds=max(0., self._clock_refresh_next-self.clock())))

board/runtime/board_speaker_business.py.text:
"""Explicit board-local speaker/anonymous/link business, without a Hub server.

One CPU worker owns the existing SpeakerDevice, progressive matcher and binding
FSMs. The encoder is injected; the board uses the already pinned ECAPA ONNX
export and the original WebRTC 30ms/mode2 gate. No model download, microphone,
network, Windows service, profile grant or device starts on import. Descriptors
contain no vectors but remain private board data and must not enter LLM prompts.
"""
from collections import OrderedDict
from concurrent.futures import ThreadPoolExecutor, TimeoutError as FutureTimeout
from contextlib import contextmanager
import copy
import hashlib
import importlib.util
import json
import math
import os
from pathlib import Path
import re
import secrets
import sqlite3
import stat
import threading
import time
from types import SimpleNamespace

from common.asr_wire import context
from common.conversation_store import conversation_id as validate_conversation_id
from common.speaker_identity import SpeakerStore, voiced_pcm
from common.speaker_turns import record
from common.speaker_visual import unavailable, validate_visual
from tools.speaker_device import SpeakerDevice
from tools.binding_hub_runtime import BindingHubRuntime
from tools.private_gallery_reference import private_gallery_reference


class SpeakerNotReady(RuntimeError):
    pass


class SpeakerBusy(SpeakerNotReady):
    pass


_OWNER = 'speaker-business-owner.json'
_NAMESPACE = 'speaker-gallery-namespace.json'
_KEY = 'identity-link-receipt.key'
_FILES = ('speakers.sqlite3', 'anonymous-voices.sqlite3', 'identity-links.sqlite3')
_MARKERS = {'speakers.sqlite3':0x41555350, 'anonymous-voices.sqlite3':0x4155414E, 'identity-links.sqlite3':0x41554C4B}
_TABLES = {
    'speakers.sqlite3': {
        'identities':{'id','name'}, 'templates':{'identity_id','model_id','dimension','embedding'},
        'metadata':{'key','value'}},
    'anonymous-voices.sqlite3': {
        'anonymous_meta':{'key','value'}, 'anonymous_labels':{'seq','cluster_id','boot','created','expires','state'},
        'anonymous_anchors':{'cluster_id','anchor'}, 'anonymous_samples':{'cluster_id','capture_id','digest'},
        'anonymous_observations':{'request_id','owner','result','received','cluster_id'}},
    'identity-links.sqlite3': {
        'linked_people':{'person_id','name','name_key','state','created'},
        'modality_links':{'person_id','modality','store_id','identity_id','model_id','revision','fingerprint','state'},
        'binding_attempts':{'attempt_id','origin','name','anonymous_id','face_guard','face_gallery','voice_gallery','state',
                            'expires','confirmed_context','face_receipt','voice_receipt','person_id','error'},
        'anonymous_person_links':{'registry_epoch','anonymous_id','person_id'},
        'binding_invalidations':{'person_id','modality','reason','at'}}}

# Added only by the explicit migration bootstrap publisher, never by ordinary
# speaker construction. This origin survives later registrations/deletions.
for _schema_tables in _TABLES.values():
    _schema_tables['bm_production_origin'] = {'slot','database_uuid','bundle_id','sources_sha256','migration_manifest_sha256'}


def _fingerprint(path):
    digest = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for chunk in iter(lambda:stream.read(1024*1024), b''):
            digest.update(chunk)
    return digest.hexdigest()


def inspect_speaker_snapshot(path, name, *, model_id):
    """Read-only exact-known-schema gate; returns hashes/counts, no values."""
    path = Path(path).absolute()
    if name not in _TABLES or path.resolve(strict=True) != path or path.is_symlink() or path.stat().st_size > 64*1024*1024:
        raise ValueError('Unsupported speaker snapshot')
    if any(Path(str(path)+suffix).exists() for suffix in ('-wal','-shm','-journal')):
        raise ValueError('Speaker source is not a quiescent snapshot')
    db = sqlite3.connect(path.as_uri()+'?mode=ro&immutable=1',uri=True,timeout=.05)
    try:
        db.execute('PRAGMA query_only=ON'); db.execute('BEGIN')
        if db.execute('PRAGMA application_id').fetchone()[0] != _MARKERS[name]:
            raise ValueError('Speaker application marker mismatch')
        if db.execute('PRAGMA user_version').fetchone()[0] != 0:
            raise ValueError('Unsupported speaker schema version')
        if db.execute('PRAGMA quick_check').fetchone()[0] != 'ok':
            raise ValueError('Speaker snapshot integrity failure')
        schema = db.execute("SELECT type,name,tbl_name,sql FROM sqlite_master WHERE name NOT LIKE 'sqlite_%' ORDER BY type,name").fetchall()
        if any(row[0] in ('trigger','view') for row in schema):
            raise ValueError('Unexpected speaker schema behavior')
        tables = {row[1] for row in schema if row[0] == 'table'}
        required = set(_TABLES[name]) - {'bm_production_origin'} - ({'binding_invalidations'} if name == 'identity-links.sqlite3' else set())
        if not required <= tables <= set(_TABLES[name]):
            raise ValueError('Unsupported speaker schema tables')
        for table in tables:
            info = db.execute('PRAGMA table_info('+table+')').fetchall()
            if {row[1] for row in info} != _TABLES[name][table]:
                raise ValueError('Unsupported speaker schema columns')
            keys = dict(identities=['id'],templates=['identity_id','model_id'],metadata=['key'],
                        anonymous_meta=['key'],anonymous_labels=['seq'],anonymous_anchors=['cluster_id'],
                        anonymous_samples=['cluster_id','capture_id'],anonymous_observations=['request_id'],
                        linked_people=['person_id'],modality_links=['modality','store_id','identity_id','model_id'],
                        binding_attempts=['attempt_id'],anonymous_person_links=['registry_epoch','anonymous_id'],
                        binding_invalidations=[],bm_production_origin=['slot'])[table]
            if [row[1] for row in sorted(info,key=lambda row:row[5]) if row[5]] != keys:
                raise ValueError('Unsupported speaker primary keys')
        if name == 'speakers.sqlite3':
            if db.execute('SELECT 1 FROM templates WHERE model_id!=? OR dimension!=192 LIMIT 1',(model_id,)).fetchone():
                raise ValueError('Speaker snapshot model changed')
        elif name == 'anonymous-voices.sqlite3':
            values = dict(db.execute("SELECT key,value FROM anonymous_meta WHERE key IN ('model_id','dimension')"))
            if values != {'model_id':model_id,'dimension':'192'}:
                raise ValueError('Anonymous snapshot model changed')
        return dict(application_id=_MARKERS[name], schema_sha256=hashlib.sha256(json.dumps(schema,sort_keys=True).encode()).hexdigest(),
                    table_count=len(tables), sha256=_fingerprint(path))
    finally:
        db.close()


def _write_json(path, value):
    path = Path(path); temp = path.with_name(path.name+'.partial-'+secrets.token_hex(4))
    fd = os.open(str(temp),os.O_WRONLY|os.O_CREAT|os.O_EXCL|getattr(os,'O_NOFOLLOW',0),0o600)
    with os.fdopen(fd,'w',encoding='utf-8') as stream:
        json.dump(value,stream,ensure_ascii=False,separators=(',',':')); stream.flush(); os.fsync(stream.fileno())
    os.replace(temp,path)


class _WriterLease:
    def __init__(self, root, *, data_origin):
        root = Path(root).absolute()
        if (not root.is_absolute() or root.resolve() != root or data_origin == 'board' and
                any(part.casefold() == 'win共享文件' for part in root.parts)):
            raise ValueError('Speaker storage must be a private regular directory')
        self.fd = None; self.root = root
        if data_origin not in ('board','synthetic'):
            raise ValueError('Explicit speaker data origin required')
        if data_origin == 'board' and os.name != 'posix':
            raise RuntimeError('Real speaker stores require the POSIX board runtime')
        root.mkdir(parents=True,exist_ok=True,mode=0o700)
        if data_origin == 'board':
            info = root.stat()
            if info.st_uid != os.getuid() or info.st_mode & 0o077 or not stat.S_ISDIR(info.st_mode):
                raise PermissionError('Speaker root must be owned by this user and private')
        path = root/'speaker-writer.lock'
        self.fd = os.open(str(path),os.O_RDWR|os.O_CREAT|getattr(os,'O_NOFOLLOW',0),0o600)
        try:
            if data_origin == 'board':
                info = os.fstat(self.fd)
                if info.st_uid != os.getuid() or info.st_mode & 0o077 or not stat.S_ISREG(info.st_mode):
                    raise PermissionError('Speaker writer lease must be private and regular')
            if os.name == 'posix':
                import fcntl
                fcntl.flock(self.fd,fcntl.LOCK_EX|fcntl.LOCK_NB)
            else:
                import msvcrt
                if os.fstat(self.fd).st_size == 0:
                    os.write(self.fd,b'0'); os.fsync(self.fd)
                os.lseek(self.fd,0,os.SEEK_SET); msvcrt.locking(self.fd,msvcrt.LK_NBLCK,1)
        except BaseException:
            os.close(self.fd); self.fd = None; raise

    def close(self):
        if self.fd is not None:
            fd,self.fd = self.fd,None
            try:
                if os.name == 'posix':
                    import fcntl
                    fcntl.flock(fd,fcntl.LOCK_UN)
                else:
                    import msvcrt
                    os.lseek(fd,0,os.SEEK_SET); msvcrt.locking(fd,msvcrt.LK_UNLCK,1)
            finally:
                os.close(fd)


class _CheckedEncoder:
    def __init__(self, encoder, current):
        self.encoder,self.current = encoder,current
        self.model_id,self.dimension = encoder.model_id,encoder.dimension
    def encode(self, pcm):
        if not self.current():
            raise InterruptedError('Speaker capture cancelled before embedding')
        value = self.encoder.encode(pcm)
        if not self.current():
            raise InterruptedError('Speaker capture cancelled during embedding')
        return value


class _GuardedStore:
    def __init__(self, store, service):
        self.original,self.service = store,service
    def __getattr__(self,key):
        return getattr(self.original,key)
    def _write(self, method, *args, **kwargs):
        service = self.service
        if not service._current():
            raise InterruptedError('Speaker write has no current capture')
        # Ownership changes serialize with the short original SQLite commit;
        # no lock spans VAD, ECAPA, model requests or spoken playback.
        with service.lock:
            job = getattr(service.local,'job',None)
            if job is None or not service._owns(job) or job['cancelled'].is_set():
                raise InterruptedError('Speaker write belongs to an old capture')
            return getattr(self.original,method)(*args,**kwargs)
    def enroll(self,*args,**kwargs):
        return self._write('enroll',*args,**kwargs)
    def delete(self,*args,**kwargs):
        return self._write('delete',*args,**kwargs)


class BoardSpeakerBusiness:
    """Create explicitly, then use bounded local jobs; one CPU/database owner."""
    @classmethod
    def create(cls, private_root, **kwargs):
        return cls(private_root,create=True,**kwargs)

    def __init__(self, private_root, *, encoder_factory, board_boot_id, quality=None,
                 expected_model_id=None, anonymous_config=None, calibration=None,
                 wall_clock=None, clock=time.monotonic, create=False, data_origin='board',
                 on_evidence=None, startup_timeout=30.):
        if create is not True:
            raise ValueError('Explicit BoardSpeakerBusiness.create is required')
        if not callable(encoder_factory) or not callable(quality) or not callable(wall_clock):
            raise SpeakerNotReady('Pinned encoder, original speech quality gate and board clock are required')
        if not re.fullmatch(r'[A-Za-z0-9_-]{1,96}',board_boot_id or ''):
            raise ValueError('Fresh board boot ID required')
        if data_origin == 'board':
            if quality is not voiced_pcm or importlib.util.find_spec('webrtcvad') is None:
                raise SpeakerNotReady('Original WebRTC mode2 30ms quality dependency is unavailable')
            if not re.fullmatch(r'ecapa-voxceleb-[0-9a-f]{64}',expected_model_id or ''):
                raise ValueError('Pinned original ECAPA model ID required')
        c = dict(calibration or {})
        if (c.get('field_calibrated',False) is not False or
                any(type(c.get(key,default)) not in (int,float) or not math.isfinite(c.get(key,default))
                    or not floor <= c.get(key,default) <= 1 for key,default,floor in
                    (('threshold',.8,.8),('margin',.1,.1),('consistency',.6,.6)))):
            raise ValueError('Keep the original uncalibrated operating policy')
        config = dict(anonymous_config or {'enabled':False})
        if (set(config)-{'enabled','threshold','margin','retention_seconds','max_clusters'}
                or type(config.get('enabled')) is not bool):
            raise ValueError('Anonymous collection requires explicit boolean configuration')
        if config['enabled']:
            from common.anonymous_voice import AnonymousPolicy
            AnonymousPolicy(threshold=config.get('threshold',.90),margin=config.get('margin',.10),
                            ttl_seconds=config.get('retention_seconds',86400),max_clusters=config.get('max_clusters',32))
        self.root = Path(private_root).absolute(); self.boot = board_boot_id
        self.clock,self.wall_clock,self.data_origin = clock,wall_clock,data_origin
        self.encoder_factory,self.quality,self.expected_model_id = encoder_factory,quality,expected_model_id
        self.config,self.calibration,self.on_evidence = config,c,on_evidence
        self.lock = threading.RLock(); self.local = threading.local(); self.closing = threading.Event()
        self.jobs = {}; self.latest = OrderedDict(); self.results = OrderedDict()
        self.last_evidence_error = None
        self.capacity = threading.BoundedSemaphore(2); self.counts = dict(submitted=0,complete=0,cancelled=0,unavailable=0,evidence_errors=0)
        self.public_state = dict(active=False,speaker_calibrated=False,automatic_profile_access=False,ready=False)
        self.lease = _WriterLease(self.root,data_origin=data_origin)
        self.pool = ThreadPoolExecutor(max_workers=1,thread_name_prefix='board-speaker-cpu')
        try:
            self.pool.submit(self._initialize).result(timeout=startup_timeout)
        except BaseException:
            self.close(timeout=1.); raise

    def _initialize(self):
        self.hub = None
        for name in _FILES+(_OWNER,_NAMESPACE,_KEY):
            if (self.root/name).is_symlink():
                raise ValueError('Speaker files cannot be symbolic links')
        owner_path = self.root/_OWNER
        owner = json.loads(owner_path.read_text(encoding='utf-8')) if owner_path.exists() else None
        if owner is None and any((self.root/name).exists() for name in _FILES):
            raise ValueError('Existing speaker stores require verified migration ownership')
        if owner is not None and (owner.get('version') != 1 or owner.get('data_origin') != self.data_origin):
            raise ValueError('Speaker origin/ownership marker mismatch')
        encoder = self.encoder_factory()
        if encoder.dimension != 192 or not isinstance(encoder.model_id,str) or not encoder.model_id:
            raise ValueError('Original ECAPA dimensions required')
        if self.expected_model_id is not None and encoder.model_id != self.expected_model_id:
            raise ValueError('Speaker encoder changed its original model ID')
        if owner is not None and owner.get('model_id') != encoder.model_id:
            raise ValueError('Speaker store model ownership changed')
        for name in _FILES:
            if (self.root/name).exists():
                inspect_speaker_snapshot(self.root/name,name,model_id=encoder.model_id)
        checked = _CheckedEncoder(encoder,self._current)
        device = SpeakerDevice(checked,self.root/'speakers.sqlite3',calibration=self.calibration,
                               clock=self.clock,quality=self._quality)
        device.store = _GuardedStore(device.store,self)
        hub = SimpleNamespace(root=self.root,speaker=device,progressive_speaker=None,binding=None,identity_links=None,
                              speaker_turns=SimpleNamespace(streaks=OrderedDict(),clock=self.clock,
                                  actor=lambda meta:(meta['board_boot_id'],meta['session_id'])))
        self.hub = hub
        namespace_path = self.root/_NAMESPACE
        if namespace_path.exists():
            namespace = json.loads(namespace_path.read_text(encoding='utf-8'))
            if (namespace.get('version') != 1 or namespace.get('model_id') != encoder.model_id
                    or not re.fullmatch(r'gallery-[0-9a-f]{32}',namespace.get('store_id',''))):
                raise ValueError('Speaker gallery namespace changed')
        elif owner is not None:
            raise ValueError('Missing owned speaker gallery namespace')
        else:
            namespace = dict(version=1,model_id=encoder.model_id,store_id='gallery-'+secrets.token_hex(16),origin='created_local')
            _write_json(namespace_path,namespace)
        def reference(identity):
            value = private_gallery_reference(self.root/'speakers.sqlite3',encoder.model_id,encoder.dimension,
                identity_id=identity,expected_application_id=SpeakerStore.APPLICATION_ID)
            value['store_id'] = namespace['store_id']
            return value
        hub.voice_reference = reference
        if self.config['enabled']:
            hub.binding = BindingHubRuntime(hub,self.config,clock=self.wall_clock,validate_root=lambda root:root,
                                            voice_reference=reference)
            hub.progressive_speaker.quality = self._quality
            hub.progressive_speaker.anonymous_store.clock = self.wall_clock
            hub.progressive_speaker.provisional.clock = self.wall_clock
        owner_value = dict(owner or {})
        owner_value.update(version=1,data_origin=self.data_origin,model_id=encoder.model_id,
                           origin=owner.get('origin') if owner else 'created_local')
        _write_json(owner_path,owner_value)
        self._refresh_public()

    def _quality(self,pcm):
        if not self._current():
            raise InterruptedError('Speaker quality no longer owns the capture')
        result = self.quality(pcm)
        if not self._current():
            raise InterruptedError('Speaker quality capture cancelled')
        return result

    def _owns(self,job):
        meta = job['meta']; actor = meta['board_boot_id'],meta['session_id']
        return self.latest.get(actor) == meta

    def _job_current(self,job):
        with self.lock:
            owned = self._owns(job)
        return (owned and not self.closing.is_set() and not job['cancelled'].is_set()
                and self.clock() < job['deadline'] and job['is_current']())

    def _current(self):
        job = getattr(self.local,'job',None)
        return job is not None and self._job_current(job)

    def _refresh_public(self):
        hub = self.hub
        binding = hub.binding if hub is not None else None
        value = dict(ready=hub is not None,active=bool(hub and (hub.speaker.sessions or binding and
                    (binding.router.active or binding.router.name_waiting))),speaker_calibrated=False,
                    automatic_profile_access=False,pcm_persisted=False,single_cpu_worker=True)
        with self.lock:
            self.public_state = value

    def public(self):
        with self.lock:
            return copy.deepcopy(self.public_state)

    def _submit(self, operation, meta, pcm, *, deadline=None, is_current=lambda:True, cancel_event=None, cid=None, control=True):
        meta = context(meta,pcm)
        if meta['board_boot_id'] != self.boot:
            raise ValueError('Speaker request belongs to another boot')
        if self.closing.is_set():
            raise SpeakerNotReady('Speaker business is closed')
        if not self.capacity.acquire(False):
            raise SpeakerBusy('The sole speaker worker is busy')
        job = dict(meta=meta,pcm=pcm,is_current=is_current,cancelled=cancel_event or threading.Event(),
                   deadline=min(self.clock()+meta['budget_ms']/1000,deadline if deadline is not None else float('inf')),
                   cid=cid,control=control)
        actor = meta['board_boot_id'],meta['session_id']
        try:
            with self.lock:
                previous = self.latest.get(actor)
                if previous is not None and (meta['generation'] < previous['generation'] or
                        meta['generation'] == previous['generation'] and meta != previous):
                    raise ValueError('Stale or reused speaker request ownership')
                self.latest[actor] = meta; self.latest.move_to_end(actor)
                while len(self.latest) > 64:
                    self.latest.popitem(last=False)
                self.jobs[id(job)] = job; self.counts['submitted'] += 1
            future = self.pool.submit(self._run,job,operation)
            job['future'] = future
            def finished(_):
                job['pcm'] = None
                with self.lock:
                    self.jobs.pop(id(job),None)
                self.capacity.release()
            future.add_done_callback(finished)
            return future,job
        except BaseException:
            job['pcm'] = None
            with self.lock:
                self.jobs.pop(id(job),None)
            self.capacity.release(); raise

    def _run(self,job,operation):
        self.local.job = job
        raw,job['pcm'] = job['pcm'],None
        try:
            if not self._current():
                raise InterruptedError('Speaker job cancelled before processing')
            value = operation(raw)
            if not self._current():
                raise InterruptedError('Speaker result no longer owns its capture')
            with self.lock:
                self.counts['complete'] += 1
            return value
        except BaseException:
            if job['control']:
                self._clear_status_receipt(job['meta'])
                if not self._current():
                    self._cancel_actor(job['meta'])
            raise
        finally:
            raw = None
            self.local.job = None
            self._refresh_public()

    def _call(self,operation,meta,pcm,**kwargs):
        future,job = self._submit(operation,meta,pcm,**kwargs)
        try:
            while True:
                if not self._job_current(job):
                    job['cancelled'].set(); job['pcm'] = None; future.cancel()
                    raise InterruptedError('Speaker request cancelled or expired')
                try:
                    value=future.result(timeout=min(.025,max(.001,job['deadline']-self.clock())))
                    if not self._job_current(job):
                        raise InterruptedError('Speaker result cancelled before adoption')
                    return value
                except FutureTimeout:
                    if future.done():
                        raise  # An operation's own timeout is not a poll timeout.
        except BaseException:
            job['cancelled'].set(); job['pcm'] = None
            if job['control']:
                # A cancellation may win after _run's final ownership check.
                # Serialize metadata invalidation after the original work, on
                # its sole worker; never undo an already committed identity.
                try:self.pool.submit(self._clear_status_receipt,job['meta'])
                except RuntimeError:pass  # Closing service cannot admit a later query.
            raise

    def route(self,meta,text,pcm,*,visual=None,gallery_packet=None,**kwargs):
        visual = validate_visual(visual,meta) if visual is not None else unavailable(meta)
        def work(raw):
            binding = self.hub.binding
            if binding is None:
                raise SpeakerNotReady('Anonymous identity-link workflow was not enabled')
            digest = None
            if gallery_packet is not None:
                from common.face_binding_wire import validate_packet
                packet = validate_packet(gallery_packet,meta)
                digest = binding.ingest_gallery(packet)['packet_sha256']
            return binding.route(meta,text,raw,visual=visual,gallery_digest=digest)
        return self._call(work,meta,pcm,**kwargs)

    def turn(self,meta,text,pcm,**kwargs):
        def work(raw):
            value = self.hub.speaker.turn(meta,text,raw)
            if self.hub.binding is not None:
                self.hub.binding.after_original_voice_turn(meta,text)
            return value
        return self._call(work,meta,pcm,**kwargs)

    def submit_analysis(self,meta,pcm,conversation_id,*,visual=None,gallery_provider=None,on_evidence=None,**kwargs):
        cid = validate_conversation_id(conversation_id); meta = context(meta,pcm)
        visual = validate_visual(visual,meta) if visual is not None else unavailable(meta)
        if gallery_provider is not None and not callable(gallery_provider):
            raise ValueError('Local read-only gallery provider must be callable')
        key = meta['board_boot_id'],meta['session_id'],meta['request_id']
        with self.lock:
            old = self.results.get(key)
            if old is not None:
                if old['meta'] != meta or old['cid'] != cid:
                    raise ValueError('Foreign speaker analysis retry')
                return copy.deepcopy(old['value'])
            analysis_deadline = min(self.clock()+12.,kwargs.get('deadline',float('inf')),self.clock()+meta['budget_ms']/1000)
            self.results[key] = dict(meta=meta,cid=cid,value=record(meta,cid,visual=visual),until=self.clock()+600,
                                     deadline=analysis_deadline,job=None)
            while len(self.results) > 256:
                self.results.popitem(last=False)
        def work(raw):
            binding = self.hub.binding
            value = binding.precomputed_analysis(meta,cid,visual) if binding is not None else None
            if value is None:
                observed_visual = visual
                if binding is not None and gallery_provider is not None:
                    # Read/hash only on the original sole CPU worker, never the
                    # foreground route or GTK tick. This is observation only:
                    # no enrollment router, consent, template or grant is made.
                    try:
                        packet = gallery_provider()
                        if not self._current():
                            raise InterruptedError('Face observation no longer owns the capture')
                        if observed_visual['state'] == 'FACE_AT_CAPTURE_BOUNDARIES':
                            age = round(self.clock()*1000)-observed_visual['evidence']['source_end_ms']
                            if not 0 <= age < 3000:
                                observed_visual = unavailable(meta,'VISUAL_EXPIRED_BEFORE_ANALYSIS')
                        reference = None
                        if packet is not None:
                            from common.face_binding_wire import validate_packet
                            packet = validate_packet(packet,meta)
                            digest = binding.ingest_gallery(packet)['packet_sha256']
                            reference = binding._gallery_for(meta,digest)
                        binding._face_reference(meta,observed_visual,reference)
                    except InterruptedError:
                        raise
                    except (OSError,ValueError,KeyError,TypeError,TimeoutError,sqlite3.Error):
                        # A bad/missing face readback cannot invent a face name
                        # or suppress an otherwise valid independent voice.
                        binding._face_reference(meta,observed_visual,None)
                analyzer = self.hub.progressive_speaker
                if analyzer is None:
                    voice,alias = self.hub.speaker.analyze(meta,raw),None
                else:
                    voice,alias = analyzer.analyze(meta,raw,is_current=self._current)
                identity = None
                if binding is not None:
                    proof = analyzer.provisional.proof(meta,store_id=self.hub.voice_reference(None)['store_id'])
                    proofs = [proof] if proof is not None else []
                    face = binding.face_naming_proof(meta,observed_visual)
                    if face is not None:
                        proofs.append(face)
                    identity = binding.registry.resolve(meta,proofs,anonymous=alias)
                value = record(meta,cid,status='COMPLETE',reason='DESCRIPTIVE_EVIDENCE_ONLY',
                               voice=voice,visual=observed_visual,anonymous=alias,identity=identity)
            return value
        try:
            kwargs['deadline'] = analysis_deadline
            future,job = self._submit(work,meta,pcm,cid=cid,control=False,**kwargs)
            with self.lock:
                if key in self.results:
                    self.results[key]['job'] = job
        except SpeakerBusy:
            value = record(meta,cid,status='UNAVAILABLE',reason='SPEAKER_WORKER_BUSY',visual=visual)
            with self.lock:
                self.results[key]['value'] = value; self.counts['unavailable'] += 1
            return copy.deepcopy(value)
        def finished(done):
            try:
                value = done.result()
            except BaseException:
                value = record(meta,cid,status='CANCELLED' if job['cancelled'].is_set() or not self._job_current(job) else 'UNAVAILABLE',
                               reason='SPEAKER_ANALYSIS_NOT_ADOPTED',visual=visual)
            with self.lock:
                row = self.results.get(key)
                if row is not None and row['meta'] == meta and row['value']['status'] == 'PENDING':
                    row['value'] = value
                    row['job'] = None
                elif row is not None:
                    value = row['value']
            callback = on_evidence or self.on_evidence
            if callback is not None and value['status'] == 'COMPLETE':
                try:
                    callback(copy.deepcopy(value))
                except Exception as exc:
                    name = type(exc).__name__
                    error = (name if name in ('PermissionError','TimeoutError','ValueError','TypeError',
                        'RuntimeError','OSError','ClockUnavailable','MemoryBusy','ScopeDenied',
                        'IdempotencyConflict') else
                        'SQLiteError' if isinstance(exc,sqlite3.Error) else 'OtherError')
                    with self.lock:
                        self.counts['evidence_errors'] += 1
                        self.last_evidence_error = dict(stage='evidence_callback',error=error)
        future.add_done_callback(finished)
        return self.analysis_result(meta,cid)

    def analysis_result(self,meta,conversation_id):
        meta = context(meta); cid = validate_conversation_id(conversation_id)
        key = meta['board_boot_id'],meta['session_id'],meta['request_id']
        with self.lock:
            row = self.results.get(key)
            if row is None or row['meta'] != meta or row['cid'] != cid or self.clock() >= row['until']:
                raise ValueError('Foreign or expired board speaker result')
            job = row['job']
            if row['value']['status'] == 'PENDING' and self.clock() >= row['deadline']:
                if job is not None:
                    job['cancelled'].set(); job['pcm'] = None
                    job.get('future').cancel() if job.get('future') is not None else None
                row['value'] = record(meta,cid,status='EXPIRED',reason='ANALYSIS_DEADLINE',visual=row['value']['visual'])
            return copy.deepcopy(row['value'])

    def analyze(self,meta,pcm,*,conversation_id,visual=None,**kwargs):
        self.submit_analysis(meta,pcm,conversation_id,visual=visual,**kwargs)
        while True:
            value = self.analysis_result(meta,conversation_id)
            if value['status'] != 'PENDING':
                return value
            time.sleep(.01)

    def begin_face_exchange(self,meta,pcm,routed,bridge,capture_snapshot,text,*,is_current=lambda:True,
                            cancel_event=None,deadline=None):
        return LocalFaceExchange(self,meta,pcm,routed,bridge,capture_snapshot,text,
                                 is_current=is_current,cancel_event=cancel_event,deadline=deadline)

    def _clear_status_receipt(self,meta):
        actor=meta['board_boot_id'],meta['session_id']
        receipts=getattr(self.hub.speaker,'save_receipts',{}) if self.hub is not None else {}
        receipt=receipts.get(actor)
        if receipt is not None and receipt['generation']<=meta['generation']:
            receipts.pop(actor,None)

    def _cancel_actor(self,meta):
        hub = self.hub; actor = meta['board_boot_id'],meta['session_id']
        self._clear_status_receipt(meta)
        hub.speaker.sessions.pop(actor,None)
        if hub.binding is not None:
            binding = hub.binding
            attempt = binding.router.active.pop(actor,None)
            if attempt is not None:
                try:
                    binding.registry.cancel(attempt,meta)
                except (ValueError,sqlite3.Error,TimeoutError):
                    pass
            binding.router.name_waiting.pop(actor,None)
            binding.speaker.sessions.pop(actor,None); binding.speaker.aliases.pop(actor,None)

    def cancel_analysis(self,meta,conversation_id):
        meta = context(meta); cid = validate_conversation_id(conversation_id)
        key = meta['board_boot_id'],meta['session_id'],meta['request_id']
        with self.lock:
            row = self.results.get(key)
            if row is None or row['meta'] != meta or row['cid'] != cid:
                raise ValueError('Foreign speaker cancellation')
            job = row['job']
            if job is not None:
                job['cancelled'].set(); job['pcm'] = None
                job.get('future').cancel() if job.get('future') is not None else None
            row['value'] = record(meta,cid,status='CANCELLED',reason='REQUEST_CANCELLED',visual=row['value']['visual'])
            return copy.deepcopy(row['value'])

    def reset(self):
        with self.lock:
            for job in self.jobs.values():
                job['cancelled'].set(); job['pcm'] = None
        def clear():
            hub = self.hub
            if hub is None:
                return
            if hub.binding is not None:
                binding = hub.binding
                for actor,attempt in tuple(binding.router.active.items()):
                    try:
                        with binding.registry._db() as db:
                            origin = db.execute('SELECT origin FROM binding_attempts WHERE attempt_id=?',(attempt,)).fetchone()
                        if origin is not None:
                            binding.registry.cancel(attempt,json.loads(origin[0]))
                    except (ValueError,sqlite3.Error,TimeoutError):
                        pass
                binding.router.active.clear(); binding.router.name_waiting.clear()
                binding.speaker.sessions.clear(); binding.speaker.aliases.clear()
            hub.speaker.sessions.clear()
            getattr(hub.speaker,'save_receipts',{}).clear()
            self._refresh_public()
        if not self.closing.is_set():
            self.pool.submit(clear)

    def health(self):
        with self.lock:
            state = copy.deepcopy(self.public_state)
            state['ready'] = state['ready'] and not self.closing.is_set()
            return dict(version=1,**state,**self.counts,
                        data_origin=self.data_origin,queued_or_active=len(self.jobs),maximum_job_slots=2,
                        last_evidence_error=copy.deepcopy(self.last_evidence_error),
                        identity_templates_exported=False,profile_grants_issued=False)

    def close(self,*,timeout=2.):
        if not self.closing.is_set():
            self.closing.set()
            with self.lock:
                for job in tuple(self.jobs.values()):
                    job['cancelled'].set(); job['pcm'] = None
                    if job.get('future') is not None:
                        job['future'].cancel()
            def finish():
                try:
                    hub = getattr(self,'hub',None)
                    if hub is not None:
                        hub.speaker.sessions.clear(); hub.speaker.store.close()
                finally:
                    self.lease.close()
            self.close_future = self.pool.submit(finish)
            self.pool.shutdown(wait=False)
        try:
            self.close_future.result(timeout=timeout)
            return True
        except FutureTimeout:
            return False  # Keep the lease until the native call actually returns.


class LocalFaceExchange:
    """Same scoped original face transaction/receipt, entirely on the board."""
    def __init__(self,business,meta,pcm,routed,bridge,capture_snapshot,text,*,is_current,cancel_event,deadline):
        self.business,self.meta,self.pcm = business,context(meta,pcm),pcm
        self.bridge,self.cancel_event = bridge,cancel_event or threading.Event()
        self.is_current,self.deadline = is_current,deadline or business.clock()+min(110,meta['budget_ms']/1000)
        self.attempt = routed['decision']['attempt_id']; self.token = secrets.token_hex(24); self.closed = False
        self.options = dict(is_current=is_current,cancel_event=self.cancel_event,deadline=self.deadline)
        def work(raw):
            return business.hub.binding.open_exchange(meta,self.attempt,self.token,min(110,max(.001,self.deadline-business.clock())))
        self.capability = business._call(work,meta,pcm,**self.options)['capability']
        self.exchange = bridge.exchange(meta,routed['binding_request'],capture_snapshot,text,self.current)

    def current(self):
        return not self.closed and not self.cancel_event.is_set() and self.business.clock()<self.deadline and self.is_current()

    @contextmanager
    def scope(self):
        if not self.current():
            raise InterruptedError('Local face exchange is no longer current')
        with self.bridge.scope(self.exchange):
            yield self

    def transform(self,value,final=True):
        if not self.current():
            raise InterruptedError('Local face result is no longer current')
        receipt = self.exchange.receipt(value,self.bridge.original_snapshot) if final else None
        raw = self.pcm
        def work(pcm):
            return self.business.hub.binding.face_result(self.meta,pcm,self.attempt,self.token,self.capability,value,
                                                        binding_receipt=receipt,final=final)
        result = self.business._call(work,self.meta,raw,**self.options)
        if final:
            self.closed = True; self.pcm = None
        return result['reply']

    def cancel(self):
        self.closed = True; self.pcm = None


def migrate_speaker_snapshots(source_root,target_root,*,expected_sha256,expected_model_id,
                              single_writer_stopped=False,data_origin='board'):
    """Import four frozen private files, preserving registry epochs and key.

    The caller first stops the sole old business writer and transfers a coherent
    snapshot directly to private board storage. This helper performs no network
    operation or live backup. It never overwrites a populated destination. The
    old namespace is derived from verified actual voice-link rows, not a name or
    caller-provided gallery string. A final private marker gates future opening.
    Returned evidence contains counts/flags only, never IDs, keys or templates.
    """
    if single_writer_stopped is not True:
        raise ValueError('A frozen single-writer handoff is required')
    names = _FILES+(_KEY,)
    if (not isinstance(expected_sha256,dict) or set(expected_sha256) != set(names)
            or any(not re.fullmatch(r'[0-9a-f]{64}',value or '') for value in expected_sha256.values())):
        raise ValueError('Every private source file requires an exact fingerprint')
    source = Path(source_root).absolute(); target = Path(target_root).absolute()
    if source.resolve() != source or source == target:
        raise ValueError('Separate regular private snapshot/destination required')
    if data_origin == 'board':
        if os.name != 'posix' or any(part.casefold() == 'win共享文件' for part in source.parts):
            raise ValueError('Source snapshots must stay in board-private storage')
        info = source.stat()
        if info.st_uid != os.getuid() or info.st_mode & 0o077:
            raise PermissionError('Snapshot directory is not private')
    for name in names:
        path = source/name
        if path.is_symlink() or not path.is_file() or _fingerprint(path) != expected_sha256[name]:
            raise ValueError('Speaker source fingerprint mismatch')
    for name in _FILES:
        inspect_speaker_snapshot(source/name,name,model_id=expected_model_id)
    if (source/_KEY).stat().st_size != 32:
        raise ValueError('Original private receipt key is invalid')
    db = sqlite3.connect((source/'identity-links.sqlite3').as_uri()+'?mode=ro&immutable=1',uri=True,timeout=.05)
    try:
        db.execute('PRAGMA query_only=ON')
        namespaces = db.execute("SELECT DISTINCT store_id,model_id FROM modality_links WHERE modality='voice' AND state='ACTIVE'").fetchall()
    finally:
        db.close()
    if len(namespaces) > 1 or namespaces and (namespaces[0][1] != expected_model_id or
            not re.fullmatch(r'gallery-[0-9a-f]{32}',namespaces[0][0] or '')):
        raise ValueError('Active original speaker gallery namespaces disagree')
    namespace = namespaces[0][0] if namespaces else 'gallery-'+secrets.token_hex(16)
    lease = _WriterLease(target,data_origin=data_origin)
    try:
        owner_path = target/_OWNER
        if owner_path.exists():
            owner = json.loads(owner_path.read_text(encoding='utf-8'))
            if (owner.get('origin') == 'imported_snapshot' and owner.get('source_sha256') == expected_sha256
                    and owner.get('model_id') == expected_model_id and owner.get('data_origin') == data_origin):
                return dict(imported=False,idempotent=True,files=4,automatic_profile_access=False)
            raise ValueError('Speaker destination is not empty')
        if any(path.name != 'speaker-writer.lock' for path in target.iterdir()):
            raise ValueError('Speaker destination is not empty')
        for name in names:
            path = target/name; temporary = target/(name+'.partial')
            fd = os.open(str(temporary),os.O_WRONLY|os.O_CREAT|os.O_EXCL|getattr(os,'O_NOFOLLOW',0),0o600)
            with os.fdopen(fd,'wb') as destination,(source/name).open('rb') as original:
                for chunk in iter(lambda:original.read(1024*1024),b''):
                    destination.write(chunk)
                destination.flush(); os.fsync(destination.fileno())
            if _fingerprint(temporary) != expected_sha256[name] or _fingerprint(source/name) != expected_sha256[name]:
                raise ValueError('Speaker snapshot changed during handoff')
            os.replace(temporary,path)
        if any(_fingerprint(source/name) != expected_sha256[name] or
               _fingerprint(target/name) != expected_sha256[name] for name in names):
            raise ValueError('Speaker snapshot changed before final handoff publication')
        _write_json(target/_NAMESPACE,dict(version=1,model_id=expected_model_id,store_id=namespace,
                                          origin='verified_active_voice_links' if namespaces else 'new_unlinked_namespace'))
        _write_json(owner_path,dict(version=1,data_origin=data_origin,model_id=expected_model_id,
                                   origin='imported_snapshot',source_sha256=expected_sha256))
        return dict(imported=True,idempotent=False,files=4,application_markers_preserved=True,
                    original_receipt_key_preserved=True,registry_epoch_preserved=True,
                    active_namespace_preserved=bool(namespaces),automatic_profile_access=False)
    finally:
        lease.close()

common/board_production_bootstrap.py.text:
"""Explicit private migration receipt gate; never creates a store on startup.

Sealing writes only after an explicit single-writer handoff. Normal verification
is read-only. Production startup may let SQLite recover an uncommitted rollback
journal while both original writer leases are held. Origin/import markers remain
mandatory. No key, template, ID or text is returned.
"""
import hashlib
import json
import os
from pathlib import Path
import re
import secrets
import sqlite3
import stat

SCHEMA = 'aura.board.production-bootstrap.v1'
ORIGIN_TABLE = 'bm_production_origin'
TARGETS = {'timeline':'timeline.sqlite3', 'speaker':'speaker/speakers.sqlite3',
           'anonymous_voice':'speaker/anonymous-voices.sqlite3', 'identity_links':'speaker/identity-links.sqlite3'}
APPLICATION_IDS = {'timeline':0x41555242, 'speaker':0x41555350,
                   'anonymous_voice':0x4155414E, 'identity_links':0x41554C4B}
ORIGIN_COLUMNS = {'slot','database_uuid','bundle_id','sources_sha256','migration_manifest_sha256'}
ORIGIN_DDL = ('CREATE TABLE bm_production_origin(slot INTEGER PRIMARY KEY CHECK(slot=1),'
              'database_uuid TEXT NOT NULL,bundle_id TEXT NOT NULL,sources_sha256 TEXT NOT NULL,'
              'migration_manifest_sha256 TEXT NOT NULL)')


class ProductionBootstrapRejected(ValueError):
    pass


def _fail(code):
    raise ProductionBootstrapRejected(code)


def _canonical(value):
    return json.dumps(value,ensure_ascii=False,sort_keys=True,separators=(',',':'),allow_nan=False)


def _digest(value):
    if not isinstance(value,str) or re.fullmatch(r'[0-9a-f]{64}',value) is None:
        _fail('invalid_fingerprint')
    return value


def _hash(path):
    value = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for part in iter(lambda:stream.read(1024*1024),b''): value.update(part)
    return value.hexdigest()


def _private_root(root):
    root = Path(root).absolute()
    if (os.name != 'posix' or root.resolve(strict=True) != root or
            any(p.casefold()=='win共享文件' for p in root.parts)):
        _fail('canonical_board_private_root_required')
    info = root.stat()
    if not stat.S_ISDIR(info.st_mode) or info.st_uid != os.getuid() or info.st_mode & 0o077:
        _fail('private_root_owner_or_mode')
    return root


def _private_file(root, relative):
    rel = Path(relative)
    if rel.is_absolute() or '..' in rel.parts:
        _fail('relative_private_target_required')
    path = root/rel
    if path.resolve(strict=True) != path or root not in path.parents:
        _fail('private_target_redirect')
    for parent in path.parents:
        if parent == root: break
        info = parent.stat()
        if not stat.S_ISDIR(info.st_mode) or info.st_uid != os.getuid() or info.st_mode & 0o077:
            _fail('private_target_parent_mode')
    info = path.stat()
    if not stat.S_ISREG(info.st_mode) or info.st_uid != os.getuid() or info.st_mode & 0o077:
        _fail('private_target_owner_or_mode')
    return path


def _db(path, write=False, *, recover=False):
    # Recovery uses SQLite's rollback handling. SQL remains query-only and a
    # missing production database is never created by either URI mode.
    mode = 'rw' if write or recover else 'ro'
    db = sqlite3.connect(path.as_uri()+'?mode='+mode,uri=True,timeout=.15,isolation_level=None)
    try:
        db.row_factory = sqlite3.Row
        if not write:
            db.execute('PRAGMA query_only=ON')
        db.execute('BEGIN IMMEDIATE' if write else 'BEGIN')
        return db
    except BaseException:
        db.close()
        raise


def _schema_hash(db, kind):
    # binding_invalidations is a known lazily-created original link table. Its
    # exact shape is checked, but its presence is not a permanent DB identity.
    rows = [tuple(r) for r in db.execute("SELECT type,name,tbl_name,sql FROM sqlite_master WHERE name NOT LIKE 'sqlite_%' ORDER BY type,name")]
    if kind == 'identity_links':
        info = db.execute('PRAGMA table_info(binding_invalidations)').fetchall()
        if info and {r['name'] for r in info} != {'person_id','modality','reason','at'}:
            _fail('link_optional_schema_changed')
        rows = [r for r in rows if r[2] != 'binding_invalidations']
    return hashlib.sha256(_canonical(rows).encode()).hexdigest()


def _read_origin(db):
    info = db.execute('PRAGMA table_info(bm_production_origin)').fetchall()
    if {r['name'] for r in info} != ORIGIN_COLUMNS or [r['name'] for r in info if r['pk']] != ['slot']:
        _fail('origin_schema_missing_or_changed')
    rows = db.execute('SELECT * FROM bm_production_origin').fetchall()
    if len(rows)!=1 or rows[0]['slot']!=1:
        _fail('origin_marker_missing_or_changed')
    return dict(rows[0])


def _import_marker(db, table, item):
    if table not in ('bm_migrations','bm_observation_migrations'):
        _fail('unknown_import_marker')
    row = db.execute('SELECT * FROM '+table+' WHERE import_id=?',(item['import_id'],)).fetchone()
    if row is None or row['state']!='complete' or row['source_sha256']!=item['source_sha256']:
        _fail('required_import_marker_missing')
    return json.loads(row['report'])


def _conversation_selection(root, db, *, initial=False, import_id=None):
    path = root/'conversation_selection.json'
    if not path.exists(): return False,None
    path = _private_file(root,path.name)
    if path.stat().st_size>1024: _fail('invalid_conversation_selection')
    try: value=json.loads(path.read_bytes())
    except (ValueError,UnicodeError): _fail('invalid_conversation_selection')
    if (not isinstance(value,dict) or set(value)!={'version','conversation_id'} or
            type(value['version']) is not int or value['version']!=1 or
            not isinstance(value['conversation_id'],str) or re.fullmatch('[0-9a-f]{32}',value['conversation_id']) is None):
        _fail('invalid_conversation_selection')
    if not db.execute("SELECT 1 FROM bm_scopes WHERE kind='conversation' AND id=?",(value['conversation_id'],)).fetchone():
        _fail('saved_conversation_scope_missing')
    if initial and not db.execute("SELECT 1 FROM bm_migration_scope_meta WHERE import_id=? "
                                 "AND scope_kind='conversation' AND scope_id=? LIMIT 1",
                                 (import_id,value['conversation_id'])).fetchone():
        _fail('saved_conversation_not_in_source_map')
    return True,_hash(path)


def register_anonymous_conversation(store, conversation_id):
    """Register an empty anonymous scope before its selection is persisted.

    This issues no profile permission and does not select/merge other scopes.
    The runtime must already hold its normal board-private writer lease.
    """
    from .board_memory import BoardMemoryStore
    if (not isinstance(store,BoardMemoryStore) or store.data_origin!='board' or
            not isinstance(conversation_id,str) or re.fullmatch('[0-9a-f]{32}',conversation_id) is None):
        _fail('invalid_anonymous_conversation_scope')
    with store._db(True) as db:
        linked=db.execute("SELECT 1 FROM sqlite_master WHERE name='bm_migration_conversation_profiles'").fetchone()
        if linked and db.execute('SELECT 1 FROM bm_migration_conversation_profiles WHERE conversation_id=?',
                                 (conversation_id,)).fetchone():
            _fail('profile_conversation_cannot_be_anonymous')
        store._ensure_scope(db,('conversation',conversation_id))
    return dict(registered=True,scope_kind='conversation',profile_grants_issued=0)


def stage_initial_conversation_selection(store, root, source_path, *, import_id):
    """Copy an explicit private legacy selection only when its anonymous scope
    was imported. No guessed fallback, profile grant or cross-scope merge.
    """
    from .board_memory import BoardMemoryStore
    root=_private_root(root)
    if not isinstance(store,BoardMemoryStore) or store.data_origin!='board' or Path(store.path).parent!=root:
        _fail('board_target_store_required')
    source=Path(source_path).absolute()
    source=_private_file(_private_root(source.parent),source.name)
    if source.stat().st_size>1024:_fail('invalid_conversation_selection')
    try:value=json.loads(source.read_bytes())
    except (ValueError,UnicodeError):_fail('invalid_conversation_selection')
    if (not isinstance(value,dict) or set(value)!={'version','conversation_id'} or type(value['version']) is not int or
            value['version']!=1 or not isinstance(value['conversation_id'],str) or
            re.fullmatch('[0-9a-f]{32}',value['conversation_id']) is None):_fail('invalid_conversation_selection')
    with store._db() as db:
        if not db.execute("SELECT 1 FROM bm_scopes s JOIN bm_migration_scope_meta m ON m.scope_kind=s.kind AND m.scope_id=s.id "
                          "WHERE s.kind='conversation' AND s.id=? AND m.import_id=?",
                          (value['conversation_id'],import_id)).fetchone():
            _fail('saved_conversation_not_an_imported_anonymous_scope')
    target=root/'conversation_selection.json'
    encoded=(_canonical(value)+'\n').encode()
    if target.exists():
        _private_file(root,target.name)
        if json.loads(target.read_bytes())!=value:_fail('different_saved_conversation_already_exists')
        return dict(conversation_selection_verified=True,idempotent=True)
    fd=os.open(str(target),os.O_WRONLY|os.O_CREAT|os.O_EXCL|getattr(os,'O_NOFOLLOW',0),0o600)
    with os.fdopen(fd,'wb') as stream:
        stream.write(encoded);stream.flush();os.fsync(stream.fileno())
    return dict(conversation_selection_verified=True,idempotent=False)


def _load_bootstrap_receipt(root, receipt_path, expected_sha256):
    """Check the pinned receipt and existing private paths before opening SQL."""
    root = _private_root(root)
    supplied = Path(receipt_path).absolute()
    if supplied.parent != root: _fail('receipt_must_be_at_private_root')
    receipt = _private_file(root,supplied.name)
    if receipt.stat().st_size>65536 or _hash(receipt)!=_digest(expected_sha256):
        _fail('receipt_fingerprint_mismatch')
    try: value = json.loads(receipt.read_bytes())
    except (ValueError,UnicodeError): _fail('invalid_receipt_json')
    required = {'schema','bundle_id','data_origin','private_root','initial_retention_enabled',
                'targets','imports','profiles_migration_verified','profiles_imported',
                'speaker_model_id','speaker_receipt_key_sha256','conversation_selection_verified',
                'conversation_selection_sha256'}
    if (not isinstance(value,dict) or set(value)!=required or value['schema']!=SCHEMA or
            value['data_origin']!='board' or value['private_root']!=str(root) or
            value['initial_retention_enabled'] is not False or value['profiles_migration_verified'] is not True or
            type(value['profiles_imported']) is not int or value['profiles_imported']<0 or
            re.fullmatch('[0-9a-f]{32}',value.get('bundle_id','')) is None or
            set(value['targets'])!=set(TARGETS) or set(value['imports'])!={'conversation','observation'}):
        _fail('receipt_schema_or_origin')
    if type(value['conversation_selection_verified']) is not bool:
        _fail('receipt_selection_proof_invalid')
    if value['conversation_selection_verified']:
        _digest(value['conversation_selection_sha256'])
    elif value['conversation_selection_sha256'] is not None:
        _fail('receipt_selection_proof_invalid')
    for kind, relative in TARGETS.items():
        if value['targets'][kind]['path'] != relative:
            _fail('unexpected_target_path')
        _private_file(root, relative)
    return root, value


def verify_production_bootstrap_receipt(root, receipt_path, expected_sha256):
    """Validate startup inputs without opening or recovering any database."""
    _load_bootstrap_receipt(root, receipt_path, expected_sha256)
    return dict(receipt_file_verified=True, database_contents_verified=False)


def _require_recovery_leases(root, leases):
    # Import only for the explicit production path to keep ordinary diagnostic
    # verification read-only and free of runtime construction.
    from board.runtime.board_business import _BoardWriterLock
    from board.runtime.board_speaker_business import _WriterLease
    if (type(leases) is not tuple or len(leases) != 2 or
            not isinstance(leases[0], _BoardWriterLock) or
            not isinstance(leases[1], _WriterLease)):
        _fail('startup_recovery_requires_original_writer_leases')
    for lease, directory, relative in (
            (leases[0], root, 'writer.lock'),
            (leases[1], root/'speaker', 'speaker/speaker-writer.lock')):
        if lease.fd is None or lease.root != directory:
            _fail('startup_recovery_writer_lease_mismatch')
        held = os.fstat(lease.fd)
        named = _private_file(root, relative).stat()
        if (held.st_dev, held.st_ino) != (named.st_dev, named.st_ino):
            _fail('startup_recovery_writer_lease_replaced')


def verify_production_bootstrap(root, receipt_path, expected_sha256, *, recovery_leases=None):
    """Verify the complete original origin/import/schema receipt.

    Ordinary callers stay read-only. The production constructor may request
    SQLite rollback recovery only under both original exclusive writer leases.
    initial_retention_enabled=False attests bootstrap policy only.
    """
    root, value = _load_bootstrap_receipt(root, receipt_path, expected_sha256)
    if recovery_leases is not None:
        _require_recovery_leases(root, recovery_leases)
    current_selection,current_selection_sha256=False,None
    for kind,relative in TARGETS.items():
        target = value['targets'][kind]
        if target['path']!=relative: _fail('unexpected_target_path')
        path = _private_file(root,relative)
        db = _db(path, recover=recovery_leases is not None)
        try:
            origin = _read_origin(db)
            if (origin['database_uuid']!=target['database_uuid'] or origin['bundle_id']!=value['bundle_id'] or
                    origin['sources_sha256']!=target['sources_sha256'] or
                    origin['migration_manifest_sha256']!=target['migration_manifest_sha256'] or
                    db.execute('PRAGMA application_id').fetchone()[0]!=APPLICATION_IDS[kind] or
                    db.execute('PRAGMA user_version').fetchone()[0]!=target['user_version'] or
                    _schema_hash(db,kind)!=target['schema_sha256'] or
                    db.execute('PRAGMA quick_check').fetchone()[0]!='ok'):
                _fail('target_origin_or_schema_changed')
            if kind == 'timeline':
                if db.execute("SELECT value FROM bm_meta WHERE key='data_origin'").fetchone()[0]!='board':
                    _fail('timeline_origin_changed')
                conversation = _import_marker(db,'bm_migrations',value['imports']['conversation'])
                _import_marker(db,'bm_observation_migrations',value['imports']['observation'])
                if conversation['profiles']!=value['profiles_imported'] or conversation['issued_profile_grants']!=0:
                    _fail('profile_migration_marker_changed')
                current_selection,current_selection_sha256 = _conversation_selection(root,db)
        finally: db.close()
    key = _private_file(root,'speaker/identity-link-receipt.key')
    if key.stat().st_size!=32 or _hash(key)!=value['speaker_receipt_key_sha256']:
        _fail('speaker_receipt_key_changed')
    # The owner marker can be serialized again by the local speaker owner.
    # Do not freeze a current epoch, gallery revision or profile count.
    owner = json.loads(_private_file(root,'speaker/speaker-business-owner.json').read_bytes())
    namespace = json.loads(_private_file(root,'speaker/speaker-gallery-namespace.json').read_bytes())
    if (owner.get('data_origin')!='board' or owner.get('origin')!='imported_snapshot' or
            owner.get('model_id')!=value['speaker_model_id'] or namespace.get('model_id')!=value['speaker_model_id'] or
            namespace.get('version')!=1):
        _fail('speaker_import_owner_changed')
    return dict(bundle_id=value['bundle_id'],data_origin='board',target_paths=dict(TARGETS),
                profiles_migration_verified=True,profiles_imported=value['profiles_imported'],
                conversation_selection_verified=current_selection,
                conversation_selection_sha256=current_selection_sha256,
                initial_conversation_selection_verified=value['conversation_selection_verified'],
                initial_retention_enabled=False,receipt_verified=True)


def seal_production_bootstrap(root, receipt_path, *, bundle_id, conversation_import,
                              observation_import, source_sha256, speaker_model_id,
                              single_writer_stopped=False):
    """Publish the private receipt LAST, after all five sources are imported.

    This does not perform a source snapshot/import or enable/start anything.
    Partial sealing is retryable only with the same bundle/source/import pins.
    """
    if single_writer_stopped is not True: _fail('single_writer_handoff_required')
    root = _private_root(root); receipt = Path(receipt_path).absolute()
    if receipt.parent!=root or receipt.exists() or re.fullmatch('[0-9a-f]{32}',bundle_id or '') is None:
        _fail('new_private_receipt_required')
    if set(source_sha256)!={'conversation','observation','speaker','anonymous_voice','identity_links'}:
        _fail('five_sources_required')
    for value in source_sha256.values(): _digest(value)
    imports = dict(conversation=conversation_import,observation=observation_import)
    for name,item in imports.items():
        if set(item)!={'import_id','source_sha256'} or item['source_sha256']!=source_sha256[name]:
            _fail('import_source_mismatch')
    manifest_hash = hashlib.sha256(_canonical(dict(sources=source_sha256,imports=imports)).encode()).hexdigest()
    targets,profile_count = {},None
    selection_verified,selection_sha256=False,None
    for kind,relative in TARGETS.items():
        path = _private_file(root,relative); db = _db(path,write=True)
        try:
            if db.execute('PRAGMA application_id').fetchone()[0]!=APPLICATION_IDS[kind]:
                _fail('target_application_mismatch')
            if kind == 'timeline':
                result = _import_marker(db,'bm_migrations',conversation_import)
                _import_marker(db,'bm_observation_migrations',observation_import)
                profile_count = result['profiles']
                if result['issued_profile_grants']!=0: _fail('unexpected_imported_grant')
                selection_verified,selection_sha256=_conversation_selection(root,db,initial=True,
                    import_id=conversation_import['import_id'])
                source_hash = hashlib.sha256(_canonical([source_sha256['conversation'],source_sha256['observation']]).encode()).hexdigest()
            else: source_hash = source_sha256[kind]
            exists = db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",(ORIGIN_TABLE,)).fetchone()
            if not exists:
                if kind!='timeline' and _hash(path)!=source_sha256[kind]:
                    _fail('speaker_target_not_exact_import_before_seal')
                db.execute(ORIGIN_DDL)
                db.execute('INSERT INTO bm_production_origin VALUES(1,?,?,?,?)',
                           (secrets.token_hex(16),bundle_id,source_hash,manifest_hash))
            origin = _read_origin(db)
            if (origin['bundle_id']!=bundle_id or origin['sources_sha256']!=source_hash or
                    origin['migration_manifest_sha256']!=manifest_hash):
                _fail('different_partial_migration_bundle')
            targets[kind] = dict(path=relative,database_uuid=origin['database_uuid'],sources_sha256=source_hash,
                migration_manifest_sha256=manifest_hash,schema_sha256=_schema_hash(db,kind),
                user_version=db.execute('PRAGMA user_version').fetchone()[0])
            db.commit()
        except BaseException:
            db.rollback(); raise
        finally: db.close()
    key = _private_file(root,'speaker/identity-link-receipt.key')
    if key.stat().st_size!=32: _fail('original_speaker_receipt_key_required')
    value = dict(schema=SCHEMA,bundle_id=bundle_id,data_origin='board',private_root=str(root),
                 initial_retention_enabled=False,targets=targets,imports=imports,
                 profiles_migration_verified=True,profiles_imported=profile_count,
                 conversation_selection_verified=selection_verified,conversation_selection_sha256=selection_sha256,
                 speaker_model_id=speaker_model_id,speaker_receipt_key_sha256=_hash(key))
    temporary = receipt.with_name(receipt.name+'.partial-'+secrets.token_hex(4))
    fd = os.open(str(temporary),os.O_WRONLY|os.O_CREAT|os.O_EXCL|getattr(os,'O_NOFOLLOW',0),0o600)
    try:
        with os.fdopen(fd,'wb') as stream:
            stream.write((_canonical(value)+'\n').encode()); stream.flush(); os.fsync(stream.fileno())
        # Verify the new private file and all immutable markers before publish.
        digest = _hash(temporary)
        verify_production_bootstrap(root,temporary,digest)
        if receipt.exists(): _fail('receipt_publish_conflict')
        os.replace(temporary,receipt)
    finally:
        if temporary.exists(): temporary.unlink()
    return dict(receipt_sha256=digest,bundle_id=bundle_id,initial_retention_enabled=False,
                profiles_imported=profile_count,target_paths=dict(TARGETS))

