"""Opt-in spoken interruption using the same visual/session/cancellation owners."""
import threading
from tools.handsfree_recording import HandsFreeRecordingController


class BargeInRecordingController(HandsFreeRecordingController):
    def __init__(self,*args,barge_capture_factory=None,**kwargs):
        super().__init__(*args,**kwargs)
        if barge_capture_factory is None:
            from tools.barge_in_capture import BargeInCapture
            from board.runtime.audio.barge_verify import InterruptionVerifier
            barge_capture_factory=lambda:BargeInCapture(self.controller.output,
                audio_frontend=self.audio_frontend,
                verifier=InterruptionVerifier(lambda:dict(self.transcriber.config),self.attention_gate.boot_id),
                spoken_text=lambda:getattr(self.controller,'reply',''))
        self.barge_factory=barge_capture_factory;self.barge_capture=None
        self.barge_id=None;self.barge_request=None;self.barge_attempt=None
        self.barge_lock=threading.Lock();self.barge_speech=None
        self.barge_error='';self.barge_interruptions=0;self.barge_last={}
        self.barge_onset_at=None;self.barge_stop_latency_ms=None
        self.tail_handoffs=0

    def _stop_barge(self):
        capture=self.barge_capture;self.barge_capture=None
        with self.barge_lock:self.barge_speech=None
        if capture:
            snapshot=capture.snapshot()
            self.barge_last={k:snapshot[k] for k in ('state','echo_reference_ready','echo_reference_gaps','speech_verification','audio_frontend') if k in snapshot}
            capture.close()

    def _finish_session(self,*args,**kwargs):
        self._stop_barge();return super()._finish_session(*args,**kwargs)

    def cancel(self):
        self._stop_barge();return super().cancel()

    def _barge_started(self,capture,request):
        current,_=self._current()
        if current and current['key']==self.monitor_key:
            with self.barge_lock:
                if capture is not self.barge_capture or request!=self.transcription.get('request_id'):return
                if self.barge_speech is None:self.monitor_stats['speech_starts']+=1
                self.barge_speech=(self.barge_id,request,self.monitor_key)
                self.barge_onset_at=self.clock()

    def _collect(self):
        capture=self.barge_capture
        if capture is not None:
            current,_=self._current()
            with self.barge_lock:proof=self.barge_speech
            if not current or current['key']!=self.monitor_key:
                self._stop_barge()  # Preserve the already accepted reply.
            elif proof:
                if proof!=(self.barge_id,self.transcription['request_id'],self.monitor_key):
                    self._stop_barge()
                elif self.early_listen and self.transcription['state']=='ANSWERED':
                    pass  # Keep the next utterance while the previous full ACK/tail settles.
                else:
                    # Never call public cancel: it would pause monitoring, lose
                    # the conversation selection and discard the new utterance.
                    self.transcriber.cancel();self.controller.cancel()
                    snapshot=capture.snapshot()
                    self.barge_last={k:snapshot[k] for k in ('state','echo_reference_ready','echo_reference_gaps','speech_verification','audio_frontend') if k in snapshot}
                    if self.barge_onset_at is not None:
                        self.barge_stop_latency_ms=round((self.clock()-self.barge_onset_at)*1000)
                    if self.capture:self.capture.close()
                    self.capture=capture;self.capture_kind='barge';self.barge_capture=None
                    with self.barge_lock:self.barge_speech=None
                    self.listen_id=self.barge_id;self.listen_started=self.clock()
                    with self.proof_lock:self.speech_proof=(self.listen_id,self.monitor_key)
                    if hasattr(self.transcriber,'capture_started'):self.transcriber.capture_started(self.listen_id)
                    self.transcription=self._empty_transcription('IDLE');self.utterance=None
                    self.recording_state='RECORDING';self.recording_error=''
                    self.rearm_at=self.ack_deadline=None;self.barge_interruptions+=1
            elif capture.snapshot()['state'] in ('ERROR','READY'):
                self.barge_error=capture.snapshot().get('error','')
                self._stop_barge()
        super()._collect()

    def _auto_tick(self):
        if (self.early_listen and self.monitor_owned and self.auto_enabled
                and self.transcription['state']=='ANSWERED' and self.barge_capture is not None):
            service=self.transcriber.public();ack=service.get('last_playback_ack') or {}
            matching=ack.get('request_id')==self.transcription['request_id']
            if (matching and not ack.get('committed') or self.clock()>=self.ack_deadline):
                self._stop_barge()
            elif (not matching or self.clock()<self.rearm_at or self._playback_active() or service.get('pending')):
                self.auto_state='SETTLING' if matching else 'WAITING_ACK'
                return
            else:
                current,reason=self._current()
                if not current or current['key']!=self.monitor_key:
                    self._finish_session(reason if not current else 'TARGET_CHANGED');return
                capture=self.barge_capture;snapshot=capture.snapshot()
                with self.barge_lock:proof=self.barge_speech
                verification=snapshot.get('speech_verification',{})
                if not proof and (verification.get('candidate') or verification.get('pending')):
                    self.auto_state='CONFIRMING_INTERRUPTION';return
                if snapshot['state']=='ERROR' or snapshot['state']=='READY' and not proof:
                    self._stop_barge()
                else:
                    if not proof and hasattr(capture,'release_for_listening') and not capture.release_for_listening():
                        self.auto_state='CONFIRMING_INTERRUPTION';return
                    if self.capture:self.capture.close()
                    with self.barge_lock:
                        self.barge_capture=None;self.barge_speech=None
                        capture.on_speech_start=self._speech_started
                    self.capture=capture;self.capture_kind='barge';self.listen_id=self.barge_id
                    self.listen_started=self.clock();self.utterance=None
                    with self.proof_lock:self.speech_proof=(self.listen_id,self.monitor_key) if proof else None
                    self.transcriber.cancel()
                    if proof and hasattr(self.transcriber,'capture_started'):self.transcriber.capture_started(self.listen_id)
                    self.transcription=self._empty_transcription('IDLE');self.recording_state='RECORDING'
                    self.recording_error='';self.rearm_at=self.ack_deadline=None
                    self.auto_state='LISTENING';self.tail_handoffs+=1
                    if not proof and capture.snapshot().get('speech_active'):self._speech_started()
                    return
        if self.transcription['state']=='ANSWERED':self._stop_barge()
        super()._auto_tick()

    def _queue_transcription(self):
        # Apply the existing raw-PCM and initial-ASR validity checks to an
        # interruption too, without selecting a different conversation ID.
        if self.capture_kind=='barge' and self.utterance is not None and self.monitor_owned:
            self.transcriber.mark_visual_entry(self.utterance.capture_id)
        super()._queue_transcription()

    def _arm_barge(self):
        tx=self.transcription;request=tx.get('request_id')
        if (not self.monitor_enabled or not self.monitor_owned or not self.monitor_entered
                or not self.auto_enabled or self._recording() or self.barge_capture is not None
                or tx['state'] not in ('GENERATING','PLAYING') or not tx.get('text')
                or not request or request==self.barge_attempt):return
        if self.transcriber.public().get('voice_enrollment',{}).get('active'):return
        current,_=self._current()
        if not current or current['key']!=self.monitor_key:return
        self.barge_attempt=request;self.barge_request=request;self.barge_error=''
        try:
            capture=self.barge_factory();self.barge_capture=capture
            capture.on_speech_start=lambda:self._barge_started(capture,request)
            self.barge_id=capture.start()
        except Exception as exc:
            self.barge_error=type(exc).__name__+': '+str(exc);self._stop_barge()

    def tick(self):
        result=super().tick();self._arm_barge();return result

    def public(self):
        state=super().public()
        state['handsfree_dialogue']['voice_barge_in']=True
        capture=self.barge_capture;snapshot=capture.snapshot() if capture else {}
        if capture:
            state['handsfree_dialogue']['microphone_open']=True
            state['audio_frontend']['current']=snapshot.get('audio_frontend',{})
        if capture and self.early_listen:
            state['handsfree_dialogue']['listening_timing']['input_ready']=bool(
                snapshot.get('input_ready',True) and snapshot.get('echo_reference_ready',False))
            state['automatic_conversation']['speech_active']=bool(
                snapshot.get('state')=='RECORDING' and snapshot.get('speech_active'))
        state['voice_barge_in']={'enabled':True,'listening':self.barge_capture is not None,
            'echo_reference_ready':snapshot.get('echo_reference_ready',False),
            'echo_reference_gaps':snapshot.get('echo_reference_gaps'),
            'interrupted_turns':self.barge_interruptions,'error':self.barge_error,
            'last_monitor':dict(self.barge_last),'last_detection_to_stop_ms':self.barge_stop_latency_ms,
            'continuation_listening':bool(self.early_listen and capture and self.transcription['state']=='ANSWERED'),
            'continuation_handoffs':self.tail_handoffs,
            'next_utterance_pending':bool(self.early_listen and capture and self.barge_speech),
            'speech_verification':snapshot.get('speech_verification',{}),
            'echo_cancellation':'SpeexDSP reference from queued playback PCM',
            'speaker_binding_verified':False}
        return state

tools/board_business_gui.py.text:
"""Opt-in bridge for the fresh r3 GTK/recording owners; no legacy host business.

The caller must supply an explicit board_business configuration. The loader
does not discover/migrate a Windows database or authorize a personal profile.
No dependency is downloaded and no microphone/player is opened here.
"""
import hashlib
import json
from pathlib import Path

from board.runtime.board_business import BoardBusinessConfig, create_board_business_runtime
from common.conversation_selection import ConversationSelection
from common.voice_wire import MAX_WAV, wav_payload


def local_feedback_provider(manifest_path):
    path = Path(manifest_path)
    if not path.is_absolute() or path.is_symlink():
        raise ValueError('Use an explicit local approved cue manifest')
    value = json.loads(path.read_text(encoding='utf-8'))
    if not isinstance(value, dict) or set(value) != {'version', 'assets'} or value['version'] != 1:
        raise ValueError('Invalid local cue manifest')
    assets = value['assets']
    if not isinstance(assets, dict) or set(assets) - {'thinking', 'arrival', 'invitation'} or 'thinking' not in assets:
        raise ValueError('The approved selected-voice thinking cue is required')
    checked = {}
    for name, row in assets.items():
        if not isinstance(row, dict) or set(row) != {'path', 'metadata'}:
            raise ValueError('Invalid local cue entry')
        audio = Path(row['path'])
        if not audio.is_absolute() or audio.is_symlink() or not audio.is_file() or audio.stat().st_size > MAX_WAV:
            raise ValueError('Invalid local cue resource')
        meta = wav_payload(row['metadata'], audio.read_bytes())
        if meta['duration_seconds'] > 5:
            raise ValueError('Local cue is too long')
        checked[name] = dict(meta, path=str(audio))
    # Playback still uses the existing verified resource, not a new copy/cache.
    return lambda: {name: dict(row) for name, row in checked.items()}


class GuiBoardBusiness:
    def __init__(self, stage, value, aura):
        if not isinstance(value, dict) or value.get('enabled') is not True:
            raise ValueError('Board business must be explicitly enabled')
        required = {'enabled', 'private_root', 'utc_bounds', 'data_origin', 'asr_directory',
                    'frontend_directory', 'feedback_manifest'}
        optional = {'model_port', 'timeout_ms', 'timezone', 'entry_mode', 'asr_threads',
                    'frontend_threads', 'visual_device_id', 'speaker'}
        if not required <= set(value) or set(value) - required - optional:
            raise ValueError('Invalid board business configuration')
        from board.runtime.audio.board_asr import BoardParaformer
        from board.runtime.audio.board_capture import BoardFrontendPool
        from board.runtime.audio.board_gtcrn_fft import BoardFftSpeechGate
        from board.runtime.audio.channel_jobs import ChannelConversationJobs
        from tools.dialogue_host_ollama import fast_system_prompt
        from common.device_policy import MODEL_HINT
        from tools.profile_control import access_from_config
        self.recording = None
        self.worker_owned = False
        self.frontend = None
        self.runtime = None
        # Pin the exact Paraformer tested on ARM; no replacement ASR model.
        asr = BoardParaformer(value['asr_directory'],
            model_sha256='f36a0433bcf096bd6d6f11b80a3ac8bed110bdca632fe0d731df8d1a84475945',
            tokens_sha256='59aba8873a2ed1e122c25fee421e25f283b63290efbde85c1f01a853d83cb6e6',
            num_threads=value.get('asr_threads', 2))
        feedback = local_feedback_provider(value['feedback_manifest'])
        self.frontend = BoardFrontendPool(BoardFftSpeechGate(value['frontend_directory'],
                                          num_threads=value.get('frontend_threads', 1)))
        config = BoardBusinessConfig(value['private_root'], tuple(value['utc_bounds']),
            model_port=value.get('model_port', 8797), timeout_ms=value.get('timeout_ms', 120000),
            timezone=value.get('timezone', 'America/Los_Angeles'), entry_mode=value.get('entry_mode', 'voice_first'),
            data_origin=value['data_origin'], visual_device_id=value.get('visual_device_id', 'board-camera'))
        try:
            self.runtime = create_board_business_runtime(config, stage.board_boot_id,
                asr=asr, system_prompt=fast_system_prompt()+MODEL_HINT,
                conversation_selection=ConversationSelection(Path(value['private_root'])/'conversation_selection.json'),
                identity_snapshot=lambda: stage.services.identity_snapshot() if stage.services is not None else None,
                identity_command=ChannelConversationJobs._identity_command,
                profile_access=access_from_config(aura), feedback_provider=feedback,
                capture_idle=self.capture_idle)
            self.runtime.initialize_clock(timeout=3.)
            speaker = value.get('speaker')
            if speaker is not None:
                self._attach_speaker(speaker, stage.board_boot_id)
            elif value['data_origin'] == 'board':
                raise ValueError('The board-owned replacement requires the existing speaker/identity business')
            self.runtime.jobs.prepare_feedback()
        except BaseException:
            self.close()
            raise

    def _attach_speaker(self, value, boot_id):
        from board.runtime.audio.board_speaker_onnx import BoardEcapaOnnxEncoder
        from board.runtime.audio.face_gallery_readback import FaceGalleryReadback
        from board.runtime.board_speaker_business import BoardSpeakerBusiness
        from common.speaker_identity import voiced_pcm
        required = {'enabled', 'model_directory', 'manifest_sha256', 'expected_model_id', 'anonymous_config'}
        if not isinstance(value, dict) or set(value) != required or value['enabled'] is not True:
            raise ValueError('Explicit pinned local speaker business configuration is required')
        fingerprint = value['manifest_sha256']
        if not isinstance(fingerprint, str) or len(fingerprint) != 64 or any(c not in '0123456789abcdef' for c in fingerprint):
            raise ValueError('The original ECAPA export manifest must be pinned')
        readback = FaceGalleryReadback.configured()
        if readback is None:
            raise ValueError('Fresh local face-gallery source binding is required')
        readback.verify(readback.config)  # Metadata/source-only check, no template export.
        service = BoardSpeakerBusiness.create(Path(self.runtime.config.private_root)/'speaker',
            encoder_factory=lambda: BoardEcapaOnnxEncoder(value['model_directory'],
                        expected_manifest_sha256=fingerprint, threads=1),
            board_boot_id=boot_id, quality=voiced_pcm, expected_model_id=value['expected_model_id'],
            anonymous_config=value['anonymous_config'], wall_clock=self.runtime.timeline.event_time,
            clock=self.runtime.clock, data_origin=self.runtime.config.data_origin)
        try:
            self.runtime.attach_speaker_business(service, face_readback=readback)
        except BaseException:
            service.close()
            raise

    @property
    def jobs(self):
        return self.runtime.jobs

    def recording_options(self, visual_controller):
        from board.runtime.audio.board_capture import BoardAutomaticCapture
        return dict(audio_frontend=None,
            auto_capture_factory=lambda *args, **kwargs: BoardAutomaticCapture(*args,
                frontend_factory=self.frontend.acquire, **kwargs),
            barge_capture_factory=self.runtime.make_barge_capture_factory(visual_controller.output,
                lambda: getattr(visual_controller, 'reply', ''), self.frontend.acquire))

    def bind_recording(self, recording):
        if recording.transcriber is not self.jobs:
            raise ValueError('Recording owner is not bound to this board dialogue job queue')
        self.recording = recording
        return recording

    def capture_idle(self):
        recording = self.recording
        if recording is None or recording.closed:
            return False
        # Silent wake listening need not prevent all future memory work.
        # A real speech onset/ASR/playback promptly makes this false.
        if recording._playback_active():
            return False
        if getattr(recording, 'barge_capture', None) is not None:
            return False
        capture = getattr(recording, 'capture', None)
        if capture is not None:
            status = capture.snapshot()
            if status.get('state') == 'ERROR' or status.get('speech_active'):
                return False
        return recording.recording_state not in ('ERROR', 'STOPPING')

    def activate(self):
        if self.recording is None:
            raise RuntimeError('Bind the existing recording/player owner before activation')
        self.worker_owned = True
        self.runtime.start()

    def close(self):
        if self.recording is not None and not self.worker_owned and not self.recording.closed:
            # Initialization failed before AvatarRenderWorker took ownership.
            # Normal live cleanup first closes that worker on its owner thread.
            self.recording.close()
        if self.frontend is not None:
            self.frontend.close()
        if self.runtime is not None:
            self.runtime.close()


def prepare_board_business(stage, value, aura):
    return GuiBoardBusiness(stage, value, aura)

