                       self.phase in ('DIALOGUE_WAITING', 'VOICE_PREPARING', 'VOICE_STARTING', 'ACTION'))
            meta = self.portrait_offload.offer(self.core, now, gain, level,
                round(self.output.position()*24000), track, waiting_for_answer=waiting)
            if meta is None or meta.get('_portrait_wait'):
                return self.last_meta, True, False
            return meta, True, meta['_portrait_burst']
