"""One live ALSA pipeline; silent PCM keeps the device ready between utterances.

Published content time always comes from the sink query, not elapsed wall time.
This engine is opt-in; the accepted padded-WAV engine remains available.
"""
import base64
from collections import deque
import hashlib
import time
import wave

from tools.gstreamer_audio_engine import OUTPUT_CAPS, validate_clip

RATE=24000
FRAMES=480
TICK_NS=20000000
MAX_FRAMES=RATE*35
MAX_APPSRC_BYTES=FRAMES*2*8
MAX_BACKPRESSURE_SECONDS=2.


def build_live_pipeline(gst,device):
    pipeline=gst.Pipeline.new('aura-persistent-audio')
    elements=[]
    try:
        for name in ('appsrc','audioconvert','audioresample','capsfilter','alsasink'):
            element=gst.ElementFactory.make(name,'aura-live-'+name)
            if element is None:raise RuntimeError('Missing GStreamer element: '+name)
            pipeline.add(element);elements.append(element)
        source,convert,resample,caps,sink=elements
        source.set_property('caps',gst.Caps.from_string('audio/x-raw,format=S16LE,layout=interleaved,rate=24000,channels=1'))
        source.set_property('format',gst.Format.TIME)
        source.set_property('is-live',True)
        source.set_property('block',False)
        source.set_property('max-bytes',MAX_APPSRC_BYTES)
        caps.set_property('caps',gst.Caps.from_string(OUTPUT_CAPS))
        sink.set_property('device',device);sink.set_property('sync',True)
        sink.set_property('buffer-time',80000);sink.set_property('latency-time',10000)
        for left,right in zip(elements,elements[1:]):
            if not left.link(right):raise RuntimeError('Cannot link persistent audio')
        return pipeline,source,sink
    except Exception:
        pipeline.set_state(gst.State.NULL)
        raise


class PersistentGstAudioEngine:
    def __init__(self,gst,device,*,clock=time.monotonic,pipeline_factory=build_live_pipeline):
        self.gst,self.device,self.clock=gst,device,clock
        self.pipeline,self.source,self.sink=pipeline_factory(gst,device)
        self.bus=self.pipeline.get_bus()
        self.next_pts=0
        self.queue=deque();self.intervals=deque()
        self.references=deque(maxlen=16);self.reference_sequence=0
        self.token=0;self.position=0.;self.answer_position=0.;self.duration=0.
        self.input_samples=0;self.answer_samples=0
        self.ready=self.done=self.paused=self.final=False
        self.active=False;self.error='';self.started_at=None;self.answer_started_at=None
        self.device_ready=False;self.audible=False;self.track=None
        self.underrun_packets=0;self.turn_underrun_packets=0;self.last_data_end=None
        self.queued_samples=0;self.last_poll_at=None;self.max_poll_gap_ms=0.;self.turn_late_rebases=0
        self._backpressure_since=None
        if self.pipeline.set_state(gst.State.PLAYING)==gst.StateChangeReturn.FAILURE:
            self.release();raise RuntimeError('Persistent ALSA start failed')

    def release(self):
        if self.pipeline is not None:self.pipeline.set_state(self.gst.State.NULL)
        self.pipeline=self.source=self.sink=None
        self.device_ready=False

    def fail(self,error):
        self.error=str(error);self.active=False;self.queue.clear();self.queued_samples=0;self.intervals.clear();self.release()

    def _reset(self,token):
        self.token=token;self.queue.clear();self.intervals.clear()
        self.position=self.answer_position=self.duration=0.
        self.input_samples=self.answer_samples=0
        self.ready=self.done=self.paused=self.final=False
        self.active=False;self.audible=False;self.track=None
        self.started_at=self.answer_started_at=self.last_data_end=None
        self.queued_samples=0;self.turn_underrun_packets=0;self.max_poll_gap_ms=0.;self.turn_late_rebases=0

    def _append(self,pcm,track):
        if not isinstance(pcm,bytes) or not pcm or len(pcm)%2:raise ValueError('Expected nonempty PCM16')
        if self.input_samples+len(pcm)//2>MAX_FRAMES:raise ValueError('Persistent queue exceeds 35 seconds')
        for offset in range(0,len(pcm),FRAMES*2):
            part=pcm[offset:offset+FRAMES*2]
            self.queue.append((part,track,self.input_samples,self.answer_samples));self.queued_samples+=len(part)//2
            self.input_samples+=len(part)//2
            if track=='answer':self.answer_samples+=len(part)//2
        self.duration=self.input_samples/RATE

    def _file(self,message,track):
        path,_=validate_clip(message['path'],message.get('sha256'))
        with wave.open(str(path),'rb') as audio:
            self._append(audio.readframes(audio.getnframes()),track)

    def command(self,message):
        token=message.get('token')
        if type(token) is not int or token<self.token:return False
        kind=message.get('type')
        if kind in ('play','stream','stop','close'):
            self._reset(token)
            if kind=='close':self.release();return True
            if kind=='stop':return True
            if not self.device_ready:raise RuntimeError('Persistent audio device is not ready')
            self.active=True
            if kind=='play':self._file(message,'answer');self.final=True
            return True
        if token!=self.token or not self.active:return False
        if kind=='pause':self.paused=bool(message.get('paused'))
        elif kind=='pcm':
            if self.final:raise ValueError('PCM after stream completion')
            if type(message.get('start_sample')) is not int or message['start_sample']!=self.answer_samples:raise ValueError('Out-of-order playback PCM')
            pcm=base64.b64decode(message.get('pcm',''),validate=True)
            if len(pcm)>FRAMES*2:raise ValueError('Playback packet exceeds 20ms')
            self._append(pcm,'answer')
        elif kind=='feedback':
            if self.answer_samples or self.final:return False
            if self.input_samples:return False  # At most one cached phrase per turn.
            self._file(message,'feedback')
        elif kind=='end':self.final=True
        else:raise ValueError('Unknown persistent audio command')
        return True

    def _push(self,pcm,pts,duration):
        gst=self.gst
        buffer=gst.Buffer.new_allocate(None,len(pcm),None)
        buffer.fill(0,pcm);buffer.pts=pts;buffer.dts=pts;buffer.duration=duration
        if self.source.emit('push-buffer',buffer)!=gst.FlowReturn.OK:
            raise RuntimeError('Persistent appsrc rejected PCM')
        # Speex's asynchronous API needs the far frame when it is QUEUED to
        # playback; delivering it after the audible frame makes it too late.
        # Playback/history clocks below still depend only on the real sink.
        self.reference_sequence+=1
        self.references.append({'sequence':self.reference_sequence,'pcm':pcm,
            'at':self.clock(),'queued_end_ns':pts+duration})

    def take_references(self):
        values=list(self.references);self.references.clear();return values

    def _has_appsrc_room(self,byte_count):
        # max-bytes only emits enough-data when block=False. This worker has
        # exactly one producer; check its real native queue before removing
        # content from our Python queue or submitting another silence packet.
        try:
            level=self.source.get_property('current-level-bytes')
            if type(level) is not int or not 0<=level<=MAX_APPSRC_BYTES:
                raise RuntimeError('Invalid persistent appsrc queue level')
        except Exception as exc:
            self.fail('Persistent appsrc queue query failed: '+type(exc).__name__+': '+str(exc)[:160])
            return False
        if level+byte_count<=MAX_APPSRC_BYTES:
            self._backpressure_since=None
            return True
        now=self.clock()
        if self._backpressure_since is None:self._backpressure_since=now
        elif now-self._backpressure_since>=MAX_BACKPRESSURE_SECONDS:
            self.fail('Persistent appsrc queue remained full for 2 seconds')
        return False

    def _observe(self,now_ns):
        self.device_ready=now_ns>=self.gst.SECOND
        self.audible=False;self.track=None
        while self.intervals and self.intervals[0][1]<=now_ns:
            start,end,token,offset,count,track,answer_offset=self.intervals.popleft()
            if token==self.token:
                if not self.ready:self.ready=True;self.started_at=self.clock()
                self.position=max(self.position,(offset+count)/RATE)
                if track=='answer':
                    self.answer_position=max(self.answer_position,(answer_offset+count)/RATE)
                    if self.answer_started_at is None:self.answer_started_at=self.clock()
        if self.intervals:
            start,end,token,offset,count,track,answer_offset=self.intervals[0]
            if token==self.token and start<=now_ns<end:
                sample=min(count,max(0,(now_ns-start)*RATE//self.gst.SECOND))
                self.position=max(self.position,(offset+sample)/RATE)
                self.audible=True;self.track=track
                if not self.ready:self.ready=True;self.started_at=self.clock()
                if track=='answer':
                    self.answer_position=max(self.answer_position,(answer_offset+sample)/RATE)
                    if self.answer_started_at is None:self.answer_started_at=self.clock()
        if self.active and self.final and not self.queue and self.last_data_end is not None and now_ns>=self.last_data_end:
            self.position=self.duration;self.answer_position=self.answer_samples/RATE
            self.done=True;self.active=False;self.audible=False;self.track=None
        elif self.active and self.final and not self.queue and self.last_data_end is None:
            self.done=True;self.active=False

    def poll(self):
        if self.pipeline is None:return self.snapshot()
        now=self.clock()
        if self.last_poll_at is not None and self.active and self.ready:
            self.max_poll_gap_ms=max(self.max_poll_gap_ms,(now-self.last_poll_at)*1000)
        self.last_poll_at=now
        gst=self.gst
        message=self.bus.timed_pop_filtered(0,gst.MessageType.ERROR)
        if message is not None:
            error,_=message.parse_error();self.fail(error);return self.snapshot()
        clock=self.pipeline.get_clock()
        if clock is None:return self.snapshot()
        running=max(0,clock.get_time()-self.pipeline.get_base_time())
        # Recover scheduling lateness without dropping or skipping content PCM.
        if self.next_pts+100000000<running:
            if self.active and self.ready:self.turn_late_rebases+=1
            self.next_pts=((running+TICK_NS-1)//TICK_NS)*TICK_NS
        for _ in range(8):
            if self.next_pts>=running+60000000:break
            content=self.active and not self.paused and bool(self.queue)
            byte_count=len(self.queue[0][0]) if content else FRAMES*2
            if not self._has_appsrc_room(byte_count):break
            pts=self.next_pts
            if content:
                pcm,track,offset,answer_offset=self.queue.popleft()
                count=len(pcm)//2;self.queued_samples-=count;duration=count*gst.SECOND//RATE
                self._push(pcm,pts,duration)
                self.intervals.append((pts,pts+duration,self.token,offset,count,track,answer_offset))
                self.last_data_end=pts+duration
            else:
                duration=TICK_NS;self._push(bytes(FRAMES*2),pts,duration)
                if self.active and self.ready and not self.paused and not self.final:
                    self.underrun_packets+=1;self.turn_underrun_packets+=1
            self.next_pts+=duration
        if self.pipeline is None:return self.snapshot()
        ok,position=self.sink.query_position(gst.Format.TIME)
        if ok and position>=0:
            self._observe(position)
        return self.snapshot()

    def snapshot(self):
        return {'token':self.token,'ready':self.ready,'clock':self.position,'done':self.done,'error':self.error,
                'started_at':self.started_at,'answer_started_at':self.answer_started_at,
                'answer_clock':self.answer_position,'audible':self.audible,'track':self.track,
                'duration':self.duration,'device_ready':self.device_ready,'persistent':True,
                'device_state':'ERROR' if self.error else 'IDLE_READY' if not self.active else 'PAUSED' if self.paused else 'PLAYING' if self.audible else 'WAITING_PCM',
                'clock_source':'GStreamer ALSA sink position query','output_caps':OUTPUT_CAPS,'device':self.device,
                'startup_silence_seconds':0.,'startup_warmup_seconds':1.,'underrun_packets':self.underrun_packets,
                'turn_underrun_packets':self.turn_underrun_packets,'queued_ms':round(self.queued_samples*1000/RATE,2),
                'max_poll_gap_ms':round(self.max_poll_gap_ms,2),'turn_late_rebases':self.turn_late_rebases}

tools/production_frontend_selection.py.text:
"""Explicit same-weight frontend and capture-thread selections, no auto-start."""


def validate_frontend_options(value):
    optimization=value.get('frontend_optimization','baseline')
    priority=value.get('capture_priority_nice',0)
    process=value.get('frontend_process',False)
    capture_process=value.get('frontend_capture_process',False)
    if type(capture_process) is not bool or capture_process and process is not True:
        raise ValueError('Automatic capture process requires explicit frontend process')
    if type(process) is not bool or process and (optimization not in ('baseline','combined') or type(value.get('frontend_threads',1)) is not int or value.get('frontend_threads',1)!=1):
        raise ValueError('Process frontend requires a reviewed mode with one model thread')
    if optimization not in ('baseline','combined'):
        raise ValueError('Choose baseline or reviewed same-weight combined frontend')
    if type(priority) is not int or priority not in (0,-10):
        raise ValueError('Capture consumer priority is disabled or fixed nice -10')
    return optimization,priority


def create_frontend_pool(directory,*,optimization,num_threads=1,frontend_process=False):
    from board.runtime.audio.board_capture import BoardFrontendPool
    if type(frontend_process) is not bool:
        raise ValueError('Explicit process frontend boolean required')
    if frontend_process:
        if optimization not in ('baseline','combined') or type(num_threads) is not int or num_threads!=1:
            raise ValueError('Process frontend requires a reviewed mode/one model thread')
        from board.runtime.audio.board_frontend_process import BoardProcessSpeechGate
        return BoardFrontendPool(BoardProcessSpeechGate(directory,num_threads=1,optimization=optimization))
    if optimization=='baseline':
        from board.runtime.audio.board_gtcrn_fft import BoardFftSpeechGate
        gate=BoardFftSpeechGate(directory,num_threads=num_threads)
    elif optimization=='combined':
        if type(num_threads) is not int or num_threads!=1:
            raise ValueError('Reviewed combined candidate requires one CPU thread')
        from board.runtime.audio.board_gtcrn_reuse import ReuseFftSpeechGate
        gate=ReuseFftSpeechGate(directory,num_threads=1,buffer_reuse=True,io_binding=True)
    else:
        raise ValueError('Unknown frontend selection; no fallback')
    return BoardFrontendPool(gate)


def priority_recording_options(gui,visual_controller):
    from board.runtime.audio.board_capture_priority import PriorityBoardAutomaticCapture,PriorityBoardBargeCapture
    return dict(audio_frontend=None,
        auto_capture_factory=lambda *args,**kwargs:PriorityBoardAutomaticCapture(*args,
            frontend_factory=gui.frontend.acquire,**kwargs),
        barge_capture_factory=gui.runtime.make_barge_capture_factory(visual_controller.output,
            lambda:getattr(visual_controller,'reply',''),gui.frontend.acquire,capture_type=PriorityBoardBargeCapture))


def automatic_capture_recording_options(gui, options):
    from board.runtime.audio.board_frontend_auto import RemoteAutomaticCapture
    def speech_start_ready(capture_id):
        recording=gui.recording
        return bool(recording is not None and ((recording.monitor_owned and recording.monitor_key) or recording.auto_enabled)
            and recording.listen_id==capture_id and recording.capture is not None
            and getattr(recording.capture,'capture_id',None)==capture_id)
    result=dict(options)
    result['auto_capture_factory']=lambda *args,**kwargs:RemoteAutomaticCapture(*args,
        frontend_pool=gui.frontend,speech_start_ready=speech_start_ready,**kwargs)
    return result

tools/yuki_business_candidate.py.text:
"""Explicit, board-local candidate pairing. Importing opens no device or store.

Only this independently packaged profile uses these adapters. Existing core,
permission, playback receipt, identity and memory implementations remain intact.
There is deliberately no live profile switch: rollback replaces the whole idle
candidate bundle, with its previous name/persona/renderer together.
"""
from dataclasses import dataclass
import hashlib
import json
import math
from pathlib import Path
import re
import threading
import types

PAIR_VERSION = 'xuefei-yuki-board-v1-candidate'
PAIR_CONFIG_SHA256 = '189b9ca394c896c606b1a7ca8f08cf16514e2051fcdca6cc568bdfc4180bbc4b'
PROFILE_ID = 'fuyukiss-yuki-freemote39-frame-mesh'
PROFILE_SHA256 = 'b7b71396c267db80a44c2b32df4ba53ded7920ac952b2fbbfebafba349f85f55'
NATIVE_PACKAGE_SHA256 = 'c0107904f8cd0b3e351666ade5fc7234e4278a82d165925dbbdc1459783baebb'


class PairRejected(ValueError):
    pass


def _read_pinned(root, relative, expected, maximum=32 * 1024 * 1024):
    relative = Path(relative)
    if relative.is_absolute() or '..' in relative.parts:
        raise PairRejected('Candidate resource must stay inside the reviewed bundle')
    path = root / relative
    if any(part.is_symlink() for part in (path, *path.parents) if part != root.parent):
        raise PairRejected('Candidate resource cannot use symlinks')
    path = path.resolve(strict=True)
    if not path.is_relative_to(root) or not path.is_file() or path.stat().st_size > maximum:
        raise PairRejected('Invalid candidate resource')
    raw = path.read_bytes()
    if hashlib.sha256(raw).hexdigest() != expected:
        raise PairRejected('Candidate resource fingerprint changed')
    return raw


class CharacterSpeechPolicy:
    """Exact reviewed addresses, without new ASR homophone assumptions.

    Raw transcription, quoted names, numbers and negation are never rewritten.
    Prefix removal is only a temporary intent-parser input; it is not a user
    event, identity name, permission, history edit or model-generated alias.
    """
    names = ('御笠雪妃', '雪妃')
    wake_words = names + ('欸', '哎')
    display_name = '雪妃'
    aliases = ()
    _punct = r'[\s，,。！？!?、：:]'
    _follow = r'(?:你|我|请|帮|陪|登记|记住|记得|长期记住|更正|忘记|查看|查询|清空|清除|删除|确认|取消|今天|现在|在吗|啊|呀)'
    _address = re.compile(
        r'^\s*(?:(?:你好[啊呀]?|嗨|嘿|喂|早上好|下午好|晚上好|早安|晚安)'
        + _punct + r'*)?(?:御笠雪妃|雪妃)(?=$|' + _punct + r'|' + _follow + r')')
    _legacy = re.compile(
        r'^\s*(?:(?:你好[啊呀]?|嗨|嘿|喂)' + _punct + r'*)?'
        r'(?:汐蓝|西兰|西蓝|溪蓝|希蓝|夕蓝|汐兰)(?=$|' + _punct + r'|' + _follow + r')')

    @staticmethod
    def prepare(text):
        if not isinstance(text, str):
            raise ValueError('Recognized speech must be text')
        return dict(raw_text=text, text=text, adjustments=[])

    def strip_address(self, text):
        if not isinstance(text, str):
            raise ValueError('Recognized speech must be text')
        match = self._address.match(text)
        if not match:
            return text
        return re.sub(r'^' + self._punct + r'+', '', text[match.end():]).strip()

    def legacy_vocative(self, text):
        return bool(isinstance(text, str) and self._legacy.match(text))

    def wake_request(self, text):
        from common.voice_wake import wake_request
        return wake_request(text, words=self.wake_words)


@dataclass(frozen=True)
class PairIdentity:
    profile_version: str
    display_name: str
    formal_name: str
    romanized_name: str
    render_profile_id: str
    render_source_profile_sha256: str
    persona_config_sha256: str
    prompt_sha256: str


class CandidatePair:
    def __init__(self, root, metadata, persona):
        self.root, self.metadata, self.persona = root, metadata, persona
        self.identity = PairIdentity(**metadata['identity'])
        self.speech = CharacterSpeechPolicy()
        self.lock = threading.RLock()
        self.mailbox = None
        self.state = 'PREPARED'
        self.failure = ''
        self.invalidators = []
        self._activate = None
        self._activation_called = False

    @property
    def selected_prompt(self):
        # Construction is permitted while the GL widget is unrealized; actual
        # jobs/context/commands all require the same ready pair before use.
        return self.persona.system_prompt

    @property
    def demo_lines(self):
        return (
            dict(id='greeting', label='雪妃问候', text='你好，我是雪妃。今天想聊些什么？', emotion='friendly', action=''),
            dict(id='happy', label='开心回应', text='太好了，又向前走了一步。我也有点开心。', emotion='happy', action=''),
            dict(id='gentle', label='轻声回应', text='先歇一会儿吧。你愿意说的话，我会认真听。', emotion='sad', action=''),
        )

    def attach_mailbox(self, mailbox):
        with self.lock:
            if self.mailbox is not None:
                raise PairRejected('One candidate pair owns exactly one native mailbox')
            self.mailbox = mailbox

    def on_ready(self, callback):
        with self.lock:
            if self._activate is not None or self._activation_called:
                raise PairRejected('Candidate startup activation is one-shot')
            self._activate = callback

    def observe_native_frame(self, stats):
        """Called only after the one local EGL widget successfully swaps.

        Source/profile hashes were validated locally before widget creation;
        frame metadata alone never authorizes an unrelated renderer or persona.
        This is readiness, not performance or visual-fidelity acceptance.
        """
        with self.lock:
            if self.state == 'FAILED' or self.mailbox is None:
                return
            if type(stats.get('frames')) is not int or stats['frames'] < 1:
                self.fail('invalid_native_readiness')
                return
            with self.mailbox.lock:
                self.mailbox._drawn = True
            self.state = 'READY'
            callback = None
            if self._activate is not None and not self._activation_called:
                self._activation_called = True
                callback = self._activate
        if callback is not None:
            try:
                callback()
            except BaseException:
                self.fail('business_activation_failed')
                raise

    def require_ready(self):
        from tools.board_persona_candidate import require_active_pair
        with self.lock:
            ready = self.state == 'READY' and self.mailbox is not None and self.mailbox.ready
            return require_active_pair(self.persona, profile_version=self.identity.profile_version,
                render_profile_id=self.identity.render_profile_id,
                render_source_profile_sha256=self.identity.render_source_profile_sha256,
                render_ready=ready)

    def ready_now(self):
        with self.lock:
            return self.state == 'READY' and self.mailbox is not None and self.mailbox.ready

    def fail(self, reason='native_unavailable'):
        with self.lock:
            first = self.state != 'FAILED'
            self.state = 'FAILED'
            if first:
                self.failure = str(reason)[:80]
            callbacks = tuple(self.invalidators) if first else ()
        # Never hold pair/GL/mailbox locks while cancelling the existing owners.
        for callback in callbacks:
            try:
                callback()
            except Exception:
                pass

    def status(self):
        with self.lock:
            return dict(profile_version=self.identity.profile_version,
                        display_name=self.identity.display_name, state=self.state,
                        selected=True, production_selected=False, fallback_allowed=False, target_fps=16,
                        render_profile_id=self.identity.render_profile_id,
                        render_source_profile_sha256=self.identity.render_source_profile_sha256,
                        prompt_sha256=self.identity.prompt_sha256, error=self.failure)


def prepare_pair(config, aura, source_hashes=None):
    """Validate only public local source/assets. No models, stores or devices."""
    value = config.get('character_pair')
    if value is None:
        if config.get('native_yuki', {}).get('enabled'):
            raise PairRejected('Native Yuki requires its atomic reviewed persona/name pair')
        return None
    if value != dict(enabled=True, profile_version=PAIR_VERSION,
                     selection='config/yuki_pair.candidate.json', selection_sha256=PAIR_CONFIG_SHA256):
        raise PairRejected('Select the exact explicit candidate pair')
    if config.get('board_business', {}).get('enabled') is not True:
        raise PairRejected('This candidate requires the existing board business factory')
    if config.get('portrait_offload', {}).get('enabled'):
        raise PairRejected('Candidate native renderer cannot coexist with portrait offload')
    if config.get('native_avatar') is not True or config.get('stable_avatar_fps') != 16:
        raise PairRejected('Candidate owns the only native sink at fixed16fps')
    root = Path(aura).resolve(strict=True)
    raw = _read_pinned(root, value['selection'], PAIR_CONFIG_SHA256, 65536)
    meta = json.loads(raw)
    if (meta['schema'] != 'aura.yuki.business_pair.v1' or
            meta['identity']['profile_version'] != PAIR_VERSION or
            meta['identity']['formal_name'] != '御笠雪妃' or
            meta['identity']['romanized_name'] != 'YUKI MIKASA' or
            meta['native_package_sha256'] != NATIVE_PACKAGE_SHA256 or
            meta['identity']['render_profile_id'] != PROFILE_ID or
            meta['identity']['render_source_profile_sha256'] != PROFILE_SHA256 or
            config.get('native_yuki') != meta['native_config']):
        raise PairRejected('Candidate renderer/persona configuration mismatch')
    for relative, expected in meta['runtime_pins'].items():
        _read_pinned(root, relative, expected)
    baseline = _read_pinned(root, 'config/yuki_accepted_prompt.baseline.txt',
                            meta['accepted_prompt_sha256'], 4096).decode('utf-8')
    from tools.board_persona_candidate import load_candidate
    persona = load_candidate((root/'config/persona.xuefei.candidate.json').resolve(strict=True),
        expected_config_sha256=meta['identity']['persona_config_sha256'],
        expected_profile_version=PAIR_VERSION, accepted_system_prompt=baseline)
    if hashlib.sha256(persona.system_prompt.encode()).hexdigest() != meta['identity']['prompt_sha256']:
        raise PairRejected('Candidate prompt fingerprint mismatch')
    if source_hashes is not None:
        source_hashes.update(meta['runtime_pins'])
        source_hashes[value['selection']] = PAIR_CONFIG_SHA256
    return CandidatePair(root, meta, persona)


def scoped_function(function, replacements):
    """A private globals dictionary; never mutates a shared imported module."""
    namespace = dict(function.__globals__)
    namespace.update(replacements)
    result = types.FunctionType(function.__code__, namespace, function.__name__,
                                function.__defaults__, function.__closure__)
    result.__kwdefaults__ = function.__kwdefaults__
    return result


def load_private_face_readback(spec):
    """Future publisher-supplied private metadata pin, with no stale fallback.

    This never opens the identity DB. The unchanged original readback performs
    its own boot/camera birth/source checks and only reads templates later in
    the existing authorized identity flow. No private configuration is bundled.
    """
    from board.runtime.audio.face_gallery_readback import FaceGalleryReadback
    if not isinstance(spec, dict) or set(spec) != {'path', 'sha256'}:
        raise PairRejected('Explicit fresh private face readback metadata pin required')
    path, expected = Path(spec['path']), spec['sha256']
    if (not path.is_absolute() or path.is_symlink() or not path.is_file()
            or path.stat().st_size > 65536 or not isinstance(expected, str)
            or re.fullmatch(r'[0-9a-f]{64}', expected) is None):
        raise PairRejected('Invalid explicit private readback metadata')
    raw = path.read_bytes()
    if hashlib.sha256(raw).hexdigest() != expected:
        raise PairRejected('Private face readback metadata fingerprint changed')
    return FaceGalleryReadback(json.loads(raw))


def validate_feedback_character(rows):
    if not isinstance(rows, dict):
        raise PairRejected('Approved public cue metadata required')
    for row in rows.values():
        text = row.get('reply_text', '')
        if not isinstance(text, str) or '汐蓝' in text:
            raise PairRejected('Approved public cue belongs to a different character')
    return rows


def selected_feedback_provider(provider, pair):
    """Never relabel or replay an old self-introduction as the new character.

    Existing reference transcripts/voice resources remain untouched. A cue
    with an old name needs a separately reviewed new cue, not text replacement.
    """
    def selected():
        pair.require_ready()
        return validate_feedback_character(provider())
    return selected


class PairedContextBuilder:
    def __init__(self, original, pair):
        self.original, self.pair = original, pair
        self.call = scoped_function(type(original).__call__, dict(prepare_spoken_input=pair.speech.prepare))
    def __call__(self, context, text, history=None):
        self.pair.require_ready()
        return self.call(self.original, context, text, history)
    def __getattr__(self, name):
        return getattr(self.original, name)


class PairedMemoryCommands:
    def __init__(self, original, pair):
        self.original, self.pair = original, pair
        self.call = scoped_function(type(original).__call__,
            dict(prepare_spoken_input=pair.speech.prepare, CHARACTER_NAME=pair.identity.display_name))
    def __call__(self, text, scope, **kwargs):
        self.pair.require_ready()
        if self.pair.speech.legacy_vocative(text):
            return None
        return self.call(self.original, self.pair.speech.strip_address(text), scope, **kwargs)


@dataclass(frozen=True)
class LocalRecordText:
    """Immutable request-local parsing text and verbatim recording input.

    The grant object is retained by identity; it is never copied, serialized,
    minted or sent to a model. No shared slot can be overwritten by a new job.
    """
    raw_record_text: str
    intent_text: str
    scope_items: tuple
    owner: object
    cancel_event: object

    @classmethod
    def capture(cls, job, text, speech):
        from common.model_inference_wire import Owner
        if not isinstance(text, str) or not 1 <= len(text) <= 4096 or '\x00' in text:
            raise PairRejected('Bounded original admitted text required')
        return cls(text, speech.strip_address(text), tuple(job.scope.items()),
                   Owner.from_dict(job.meta), job.cancelled)

    def same_scope(self, scope):
        if not isinstance(scope, dict):
            return False
        original = dict(self.scope_items)
        return (scope.keys() == original.keys() and
                all(scope[key] is value if key == 'grant' else scope[key] == value
                    for key, value in original.items()))


@dataclass(frozen=True)
class LocalRecordController:
    """Per-request proxy for exactly the two local recording entrypoints.

    Parsers/producers still consume intent_text. Only same-scope user_said is
    recorded from raw_record_text. Explicit device_event queries keep their
    intentionally normalized input, device scope, claims and original guards.
    Playback plans, stores, grants, clocks and receipts remain original objects.
    """
    original: object
    texts: LocalRecordText

    def __getattr__(self, name):
        return getattr(self.original, name)

    def _record_text(self, text, kwargs, input_source):
        owner = self.texts.owner
        if (self.original.board_boot_id != owner.board_boot_id or
                kwargs.get('session_id') != owner.session_id or
                kwargs.get('generation') != owner.generation or
                kwargs.get('turn_id') != owner.request_id or
                kwargs.get('cancel_event') is not self.texts.cancel_event):
            raise PairRejected('Local recording proxy belongs to another request')
        if input_source != 'user_said':
            return text
        scope = kwargs.get('scope')
        if not self.texts.same_scope(scope) or scope.get('kind') not in ('conversation', 'profile'):
            raise PairRejected('Raw user input cannot move to another or device scope')
        return self.texts.raw_record_text

    def prepare_local_sequence(self, text, producer, chunk_sink, **kwargs):
        return self.original.prepare_local_sequence(
            self._record_text(text, kwargs, 'user_said'), producer, chunk_sink, **kwargs)

    def prepare_local_reply(self, text, reply_factory, *, input_source='user_said', **kwargs):
        return self.original.prepare_local_reply(
            self._record_text(text, kwargs, input_source), reply_factory,
            input_source=input_source, **kwargs)


def bind_runtime_pair(runtime, pair):
    """Attach once before any worker starts, retaining the exact store/owners."""
    from tools import yuki_jobs_candidate
    if (runtime.started or runtime.closed or runtime.jobs.thread is not None or
            not runtime.controller.idle or hasattr(runtime.jobs, 'character_pair')):
        raise PairRejected('Pair only a fresh idle board business instance')
    builder, commands = runtime.controller.context_builder, runtime.controller.command_handler
    if builder.system_prompt != pair.selected_prompt:
        raise PairRejected('Factory prompt is not the selected atomic pair')
    new_builder = PairedContextBuilder(builder, pair)
    new_commands = PairedMemoryCommands(commands, pair)
    original_enabled, original_submit = runtime.jobs.enabled, runtime.jobs.submit
    def enabled():
        return pair.ready_now() and original_enabled()
    def submit(clip):
        pair.require_ready()
        return original_submit(clip)
    original_idle = runtime._foreground_idle
    def foreground_idle():
        return pair.ready_now() and original_idle()
    # All work below is metadata/method binding, before start(). No copied
    # queues, grants, scope, Store, profiles, identity guide or player owner.
    runtime.jobs.character_pair = pair
    runtime.jobs._admit_text = types.MethodType(yuki_jobs_candidate._admit_text, runtime.jobs)
    runtime.jobs._route = types.MethodType(yuki_jobs_candidate._route, runtime.jobs)
    runtime.jobs.enabled, runtime.jobs.submit = enabled, submit
    runtime._foreground_idle = foreground_idle
    runtime.controller.context_builder = new_builder
    runtime.controller.command_handler = new_commands
    pair.invalidators.append(runtime.jobs.cancel)
    runtime.character_pair = pair


class CandidateMonitorChoice:
    """This unselected candidate never resumes a persisted microphone choice.

    Future explicit operator toggles are RAM-only for this candidate process;
    the production preference file is neither read nor overwritten.
    """
    def __init__(self, pair):
        self.pair, self.enabled = pair, False
        pair.invalidators.append(lambda: self.write(False))
    def read(self):
        return self.enabled and self.pair.ready_now()
    def write(self, enabled):
        if type(enabled) is not bool:
            raise ValueError('Expected boolean monitoring choice')
        if enabled:
            self.pair.require_ready()
        self.enabled = enabled


class NumericFacials:
    """The original envelope values, without loading old eye/mouth/body PNGs."""
    def __init__(self, core, *, expressive_body=False):
        self.core = core
        self.envelope = self.closing = None
        self.last_gain = self.last_level = 0.
        self.last_asset = None
    def begin(self, envelope):
        self.envelope = envelope
        self.closing = None
        self.last_gain = self.last_level = 0.
    def stop(self, now):
        self.envelope = self.closing = None
        self.last_gain = self.last_level = 0.
    def values(self, audio_time, playing, now):
        from tools.facial_layers import interpolate
        if playing and self.envelope:
            return (interpolate(self.envelope['gains'], audio_time, self.envelope['hop_seconds']),
                    interpolate(self.envelope['levels'], audio_time, self.envelope['hop_seconds']))
        return 0., 0.
    def apply(self, *args):
        raise PairRejected('Old PNG composition is disabled for this selected native profile')


def create_native_core():
    from board.interaction.avatar_player import AvatarPlayer
    class NativeLogicCore(AvatarPlayer):
        # The same production FSM/generation/reply/burst policy, no legacy
        # asset preload/sequence/SOP/pixel evaluation or old body seed work.
        def pool(self, state):
            return ()
        def sequence(self, *args, **kwargs):
            raise PairRejected('Old PNG sequences are disabled for the candidate')
        def sop(self, *args, **kwargs):
            raise PairRejected('Old PNG motion tables are disabled for the candidate')
        def display_frame(self, *args, **kwargs):
            raise PairRejected('Native failure cannot fall back to old PNG rendering')
    return NativeLogicCore()


def native_controller_type():
    from tools.streaming_controller import StreamingController
    from tools.realtime_controller import RealtimeController
    init = scoped_function(RealtimeController.__init__, dict(RealtimeFacials=NumericFacials))
    class NativeStreamingController(StreamingController):
        def __init__(self, *args, **kwargs):
            self.stream = None
            self.completed_streams = []
            init(self, *args, **kwargs)
    # channel_event/tick/completion/pause/cancel are inherited byte-for-byte.
    return NativeStreamingController
